    def _budget_remaining(self, name):
        return max(0, self._budget_limits().get(name, 0) - int(self.budget_counts.get(name, 0)))

    def _consume_budget(self, name):
        self.budget_counts[name] = int(self.budget_counts.get(name, 0)) + 1

    def _refund_budget(self, name):
        self.budget_counts[name] = max(0, int(self.budget_counts.get(name, 0)) - 1)

    def _deterministic_guard(self, telemetry):
        reasons = []
        checks = [
            ("active_event", self._float(telemetry.get("active_event_memory")) > 0),
            ("event_continuity", self._float(telemetry.get("gmq_event_continuity_risk")) >= 0.35),
            ("foreground_risk", self._float(telemetry.get("foreground_risk")) >= 0.55),
            ("final_sanitizer", self._float(telemetry.get("final_sanitizer_active")) > 0),
            ("ptz_closed_empty_kill", self._float(telemetry.get("ptz_closed_empty_kill_active")) > 0 or self._float(telemetry.get("closed_empty_blocked_under_ptz")) > 0),
            ("global_motion_safety", self._float(telemetry.get("global_motion_escape_active")) > 0 or self._float(telemetry.get("gmq_event_hard_veto_active")) > 0),
            ("low_framerate_cadence", self._float(telemetry.get("low_framerate_cadence_guard_active")) > 0 or self._float(telemetry.get("low_framerate_detector_floor_active")) > 0),
            ("explicit_safety_event", (
                self._float(telemetry.get("closed_empty_blocked_final")) > 0
                or self._float(telemetry.get("reuse_blocked_final")) > 0
                or self._float(telemetry.get("lightweight_blocked_final")) > 0
                or self._float(telemetry.get("event_fn_risk_frames")) > 0
                or self._float(telemetry.get("event_closed_empty_blocked_count")) > 0
            )),
        ]
        for reason, active in checks:
            if active:
                reasons.append(reason)
        return bool(reasons), "+".join(dict.fromkeys(reasons))

