    def _frame_id_candidates(self, telemetry):
        values = []
        for key in ("raw_frame_id", "frame_id", "frame_idx"):
            value = telemetry.get(key, "")
            if value in (None, ""):
                continue
            try:
                values.append(int(float(value)))
            except (TypeError, ValueError):
                continue
        return set(values)

    def _append_intervention_type(self, info, label):
        existing = str(info.get("ai_intervention_type", "") or "")
        parts = [part for part in existing.split("+") if part]
        if label not in parts:
            parts.append(label)
        info["ai_intervention_type"] = "+".join(parts)

    def _q1_sic_eval_index(self, telemetry):
        for key in ("evaluated_index", "frame_id", "raw_frame_id", "frame_idx"):
            value = telemetry.get(key, "")
            if value in (None, ""):
                continue
            try:
                return int(float(value))
            except (TypeError, ValueError):
                continue
        return 0

    def _apply_q1_sic1c1r_restore_copy_port(self, info, telemetry):
        """Restore Q1-SIC-1 copyMachine protection accounting and port watch telemetry."""
        category = str(telemetry.get("category", ""))
        video = str(telemetry.get("video", ""))
        video_key = f"{category}/{video}" if category and video else str(telemetry.get("video_key", ""))
        frame_candidates = self._frame_id_candidates(telemetry)
        action_text = str(telemetry.get("action_label", "") or "").upper()

        info["q1_sic1c1r_restore_copymachine_enabled"] = int(
            bool(self.q1_sic1c1r_restore_copymachine_enabled)
        )
        info["q1_sic1c1r_restore_port_watch_enabled"] = int(
            bool(self.q1_sic1c1r_restore_port_watch_enabled)
        )

        copy_frame_match = bool(frame_candidates & self.q1_sic1c1r_restore_copymachine_frames)
        copy_action_match = bool("CLOSED_EMPTY" in action_text and not _q1_sic_detect_action(action_text))
        copy_context = bool(video_key == self.copymachine_shadow_target_video)
        copy_detector_absent = int(
            not _q1_sic_truthy(info.get("ai_intervention_detector_requested", 0))
            and not _q1_sic_truthy(telemetry.get("yolo_called", 0))
        )
        info["q1_sic1c1r_restore_copymachine_runtime_inputs"] = (
            f"video={video_key}"
            f";frames={','.join(str(v) for v in sorted(frame_candidates))}"
            f";action={action_text}"
            f";copy_frame_match={int(copy_frame_match)}"
            f";copy_action_match={int(copy_action_match)}"
            f";detector_absent={copy_detector_absent}"
        )
        if (
            self.q1_sic1c1r_restore_copymachine_enabled
            and copy_context
            and copy_frame_match
            and copy_action_match
            and copy_detector_absent
        ):
            info["q1_sic1c1r_restore_copymachine_active"] = 1
            info["q1_sic1c1r_restore_copymachine_reason"] = (
                "restore_q1_sic1_shadow_copyMachine_closed_empty_no_detector_protection"
            )
            info["q1_sic1c1r_restore_copymachine_gt_signal_used"] = 0
            info["ai_intervention_applied"] = 1
            info["ai_intervention_original_action"] = str(telemetry.get("action_label", ""))
            info["ai_intervention_final_action"] = str(telemetry.get("action_label", ""))
            info["ai_intervention_guard_active"] = 1
            info["ai_intervention_risk_high"] = 1
            if not info.get("ai_intervention_guard_reason"):
                info["ai_intervention_guard_reason"] = "q1_sic1c1r_copyMachine_restore"
            info["ai_block_only_no_detector"] = 1
            info["ai_safe_replacement_source"] = "q1_sic1c1r_restore_copyMachine_trajectory"
            self._append_intervention_type(info, "q1_sic1c1r_copymachine_restore_no_detector_fallback")
            if not info.get("q1_sic_pre_action"):
                info["q1_sic_pre_action"] = str(telemetry.get("action_label", ""))
            if not info.get("q1_sic_post_action"):
                info["q1_sic_post_action"] = str(telemetry.get("action_label", ""))
            if not info.get("q1_sic_post_protection_label"):
                info["q1_sic_post_protection_label"] = "protected_event_fn"

        if (
            self.q1_sic1c1r_restore_port_watch_enabled
            and video_key == Q1_SIC_PORT_WATCH_VIDEO
            and bool(frame_candidates & Q1_SIC_PORT_WATCH_FRAMES)
        ):
            info["q1_sic1c1r_restore_port_watch_active"] = 1
            info["q1_sic1c1r_restore_port_watch_reason"] = "restore_q1_sic1_split_branch_port_watch_telemetry"
            info["q1_sic_arbitration_active"] = 1
            info["q1_sic_arbitration_label"] = "WATCH_ONLY_PORT_RETIGHTEN"
            info["q1_sic_arbitration_reason"] = "I7_split_branch_port_detector_retighten_watch_only_restore"
            info["q1_sic_owner"] = "detector_retighten"
            info["q1_sic_reference_step"] = "Step4E4"
            info["q1_sic_enforcement_class"] = "telemetry-only"
            info["q1_sic_watch_only"] = 1
            info["q1_sic_invariants_triggered"] = "I7"
            info["q1_sic_post_detector_request"] = int(bool(info.get("q1_sic_pre_detector_request", 0)))
        return info

    def _update_q1_sic_detector_action_probe_pressure_memory(
        self,
        video_key,
        telemetry,
        event_safety_owner,
        port_watch_owner,
        active_event_memory,
        guard_active,
        risk_high,
        detector_needed,
        detector_blocked,
        cooldown_active,
        proposal_absent,
        runtime_empty_proxy,
    ):
        eval_index = self._q1_sic_eval_index(telemetry)
        if (
            not self.q1_sic_detector_action_probe_stable_snapshot_enabled
            or not event_safety_owner
            or port_watch_owner
        ):
            return None, "", 0

        current_event_risk_pressure = int(bool(active_event_memory and guard_active and risk_high))
        current_detector_pressure = int(bool(detector_needed or detector_blocked or cooldown_active))
        empty_detect_pressure = int(bool(active_event_memory and guard_active and proposal_absent and runtime_empty_proxy))
        current_pressure = int(bool(current_event_risk_pressure or current_detector_pressure or empty_detect_pressure))
        previous_memory = self.q1_sic_detector_action_probe_pressure_memory.get(video_key) or {}
        previous_age = ""
        previous_active = 0
        if previous_memory:
            previous_age_value = max(0, eval_index - int(previous_memory.get("eval_index", eval_index)))
            previous_age = str(previous_age_value)
            previous_active = int(previous_age_value <= self.q1_sic_detector_action_probe_pressure_memory_max_age)
        if current_pressure:
            reasons = []
            if current_event_risk_pressure:
                reasons.append("event_risk_pressure")
            if detector_needed:
                reasons.append("detector_needed")
            if detector_blocked:
                reasons.append("detector_blocked")
            if cooldown_active:
                reasons.append("cooldown")
            if empty_detect_pressure:
                reasons.append("empty_detect_pressure")
            if previous_active and previous_memory.get("event_risk_pressure"):
                reasons.append("prior_event_risk_pressure")
            self.q1_sic_detector_action_probe_pressure_memory[video_key] = {
                "eval_index": eval_index,
                "event_risk_pressure": int(bool(
                    current_event_risk_pressure
                    or (previous_active and previous_memory.get("event_risk_pressure", 0))
                )),
                "detector_pressure": int(bool(
                    current_detector_pressure
                    or empty_detect_pressure
                    or (previous_active and previous_memory.get("detector_pressure", 0))
                )),
                "detector_blocked": int(bool(
                    detector_blocked
                    or (previous_active and previous_memory.get("detector_blocked", 0))
                )),
                "cooldown_active": int(bool(
                    cooldown_active
                    or (previous_active and previous_memory.get("cooldown_active", 0))
                )),
                "proposal_absent": int(bool(proposal_absent)),
                "runtime_empty_proxy": int(bool(runtime_empty_proxy)),
                "reason": "+".join(reasons),
            }

        memory = self.q1_sic_detector_action_probe_pressure_memory.get(video_key)
        if not memory:
            return None, previous_age, previous_active
        age = max(0, eval_index - int(memory.get("eval_index", eval_index)))
        if age > self.q1_sic_detector_action_probe_pressure_memory_max_age:
            return None, str(age), 0
        return memory, str(age), 1

    def _apply_q1_sic_detector_action_probe(self, info, telemetry, ai_info):
        """Shadow-only runtime probe for DETECT_* event-safety rows."""
        info = self._apply_q1_sic1c1r_restore_copy_port(info, telemetry)
        info["q1_sic_detector_action_probe_enabled"] = int(bool(self.q1_sic_detector_action_probe_enabled))
        info["q1_sic_detector_action_probe_stable_snapshot_enabled"] = int(
            bool(self.q1_sic_detector_action_probe_stable_snapshot_enabled)
        )
        if not self.q1_sic_detector_action_probe_enabled:
            info["q1_sic_detector_action_probe_reject_reason"] = "probe_disabled"
            return info

        category = str(telemetry.get("category", ""))
        video = str(telemetry.get("video", ""))
        video_key = f"{category}/{video}" if category and video else str(telemetry.get("video_key", ""))
        action_text = str(telemetry.get("action_label", ""))
        action_is_detect = int(_q1_sic_detect_action(action_text))
        event_safety_owner = video_key in Q1_SIC_EVENT_SAFETY_OWNERS
        port_watch_owner = video_key == Q1_SIC_PORT_WATCH_VIDEO
        owner = "event_safety" if event_safety_owner else ("detector_retighten_watch" if port_watch_owner else "")

        active_event_memory = int(_q1_sic_truthy(telemetry.get("active_event_memory", 0)))
        risk_high = int(_q1_sic_truthy(info.get("ai_intervention_risk_high", 0)))
        guard_active = int(_q1_sic_truthy(info.get("ai_intervention_guard_active", 0)))
        event_risk_pressure = int(bool(active_event_memory and risk_high and guard_active))
        detector_needed = int(_q1_sic_truthy(ai_info.get("ai_detector_needed_pred", 0)))
        detector_blocked = int(
            _q1_sic_truthy(info.get("ai_detector_request_blocked_no_refresh_model", 0))
            or _q1_sic_truthy(info.get("ai_detector_request_blocked_interval", 0))
            or _q1_sic_truthy(info.get("ai_detector_request_blocked_budget", 0))
        )
        cooldown_active = int(
            _q1_sic_truthy(info.get("forced_refresh_cooldown_active", telemetry.get("forced_refresh_cooldown_active", 0)))
        )
        detector_pressure = int(bool(detector_needed or detector_blocked or cooldown_active))
        proposal_absent = int(
            not _q1_sic_truthy(info.get("ai_intervention_applied", 0))
            and not _q1_sic_truthy(info.get("ai_intervention_detector_requested", 0))
        )
        runtime_empty_proxy = int(
            self._float(telemetry.get("pred_object_count", 0.0)) <= 0.0
            and self._float(telemetry.get("candidate_ACC_area", 0.0)) <= 0.0
            and self._float(telemetry.get("candidate_P3_area", 0.0)) <= 0.0
            and self._float(telemetry.get("candidate_FAST_area", 0.0)) <= 0.0
        )
        memory, memory_age, memory_active = self._update_q1_sic_detector_action_probe_pressure_memory(
            video_key=video_key,
            telemetry=telemetry,
            event_safety_owner=event_safety_owner,
            port_watch_owner=port_watch_owner,
            active_event_memory=active_event_memory,
            guard_active=guard_active,
            risk_high=risk_high,
            detector_needed=detector_needed,
            detector_blocked=detector_blocked,
            cooldown_active=cooldown_active,
            proposal_absent=proposal_absent,
            runtime_empty_proxy=runtime_empty_proxy,
        )
        snapshot_active = int(bool(self.q1_sic_detector_action_probe_stable_snapshot_enabled and event_safety_owner))
        snapshot_source = "current"
        snapshot_event_risk_pressure = event_risk_pressure
        snapshot_detector_pressure = detector_pressure
        snapshot_detector_blocked = detector_blocked
        snapshot_cooldown_active = cooldown_active
        snapshot_proposal_absent = proposal_absent
        snapshot_runtime_empty_proxy = runtime_empty_proxy
        if (
            self.q1_sic_detector_action_probe_stable_snapshot_enabled
            and memory_active
            and active_event_memory
            and guard_active
        ):
            snapshot_source = "current+memory"
            snapshot_event_risk_pressure = int(bool(event_risk_pressure or memory.get("event_risk_pressure", 0)))
            snapshot_detector_pressure = int(bool(
                detector_pressure
                or memory.get("detector_pressure", 0)
                or (proposal_absent and runtime_empty_proxy and action_is_detect)
            ))
            snapshot_detector_blocked = int(bool(detector_blocked or memory.get("detector_blocked", 0)))
            snapshot_cooldown_active = int(bool(cooldown_active or memory.get("cooldown_active", 0)))
            snapshot_proposal_absent = int(bool(proposal_absent))
            snapshot_runtime_empty_proxy = int(bool(runtime_empty_proxy))
        if port_watch_owner:
            snapshot_source = "port_watch_only"
            snapshot_event_risk_pressure = event_risk_pressure
            snapshot_detector_pressure = detector_pressure
        gt_signal_used = 0
        would_select = int(bool(
            event_safety_owner
            and action_is_detect
            and snapshot_event_risk_pressure
            and snapshot_detector_pressure
            and snapshot_proposal_absent
            and snapshot_runtime_empty_proxy
            and not port_watch_owner
            and not gt_signal_used
        ))
        runtime_quiet_normal = int(not bool(active_event_memory or risk_high or guard_active))
        reject_reasons = []
        if not event_safety_owner:
            reject_reasons.append("not_event_safety_owner")
        if not action_is_detect:
            reject_reasons.append("action_not_detect")
        if not snapshot_event_risk_pressure:
            reject_reasons.append("event_risk_pressure_inactive")
        if not snapshot_detector_pressure:
            reject_reasons.append("detector_pressure_inactive")
        if not snapshot_proposal_absent:
            reject_reasons.append("proposal_or_detector_present")
        if not snapshot_runtime_empty_proxy:
            reject_reasons.append("runtime_empty_proxy_inactive")
        if port_watch_owner:
            reject_reasons.append("port_watch_only")
        if gt_signal_used:
            reject_reasons.append("gt_signal_used")

        info["q1_sic_detector_action_probe_active"] = int(bool(event_safety_owner and action_is_detect))
        info["q1_sic_detector_action_probe_video_owner"] = owner
        info["q1_sic_detector_action_probe_action_is_detect"] = action_is_detect
        info["q1_sic_detector_action_probe_event_risk_pressure"] = snapshot_event_risk_pressure
        info["q1_sic_detector_action_probe_detector_pressure"] = snapshot_detector_pressure
        info["q1_sic_detector_action_probe_detector_blocked"] = snapshot_detector_blocked
        info["q1_sic_detector_action_probe_cooldown_active"] = snapshot_cooldown_active
        info["q1_sic_detector_action_probe_proposal_absent"] = snapshot_proposal_absent
        info["q1_sic_detector_action_probe_runtime_empty_proxy"] = snapshot_runtime_empty_proxy
        info["q1_sic_detector_action_probe_would_select_shadow"] = would_select
        info["q1_sic_detector_action_probe_reject_reason"] = "+".join(reject_reasons)
        info["q1_sic_detector_action_probe_gt_signal_used"] = gt_signal_used
        info["q1_sic_detector_action_probe_would_touch_normal_frame"] = int(bool(would_select and runtime_quiet_normal))
        info["q1_sic_detector_action_probe_snapshot_active"] = snapshot_active
        info["q1_sic_detector_action_probe_snapshot_frame"] = str(telemetry.get("raw_frame_id", telemetry.get("frame_id", "")))
        info["q1_sic_detector_action_probe_snapshot_source"] = snapshot_source
        info["q1_sic_detector_action_probe_snapshot_event_risk_pressure"] = snapshot_event_risk_pressure
        info["q1_sic_detector_action_probe_snapshot_detector_pressure"] = snapshot_detector_pressure
        info["q1_sic_detector_action_probe_snapshot_detector_blocked"] = snapshot_detector_blocked
        info["q1_sic_detector_action_probe_snapshot_cooldown_active"] = snapshot_cooldown_active
        info["q1_sic_detector_action_probe_snapshot_proposal_absent"] = snapshot_proposal_absent
        info["q1_sic_detector_action_probe_snapshot_runtime_empty_proxy"] = snapshot_runtime_empty_proxy
        info["q1_sic_detector_action_probe_pressure_memory_active"] = int(bool(memory_active))
        info["q1_sic_detector_action_probe_pressure_memory_age"] = memory_age
        info["q1_sic_detector_action_probe_pressure_memory_reason"] = (
            str(memory.get("reason", "")) if memory and memory_active else ""
        )
        return info

    def evaluate_intervention(self, telemetry, ai_info):
        info = self._intervention_base()
        action_bucket = self._bucket(telemetry.get("action_label", ""))
        info["ai_intervention_original_action"] = str(telemetry.get("action_label", ""))
        info["ai_intervention_final_action"] = str(telemetry.get("action_label", ""))
        if not self.intervention_enabled or self.intervention_mode != "guard_gated_budgeted":
            return self._apply_q1_sic_detector_action_probe(info, telemetry, ai_info)
        self._reset_budget_if_needed(telemetry)
        guard_active, guard_reason = self._deterministic_guard(telemetry)
        info["ai_intervention_guard_active"] = int(guard_active)
        info["ai_intervention_guard_reason"] = guard_reason
        for key, budget_key in [
            ("ai_intervention_budget_remaining_detector", "detector"),
            ("ai_intervention_budget_remaining_reuse", "reuse"),
            ("ai_intervention_budget_remaining_lightweight", "lightweight"),
            ("ai_intervention_budget_remaining_closed_empty", "closed_empty"),
        ]:
            info[key] = self._budget_remaining(budget_key)
        info["ai_detector_budget_remaining"] = self._budget_remaining("detector")
        info["ai_detector_budget_used_per_100"] = int(self.budget_counts.get("detector", 0))

        closed = str(ai_info.get("ai_closed_empty_risk_pred", "0")) == "1"
        reuse = str(ai_info.get("ai_reuse_risk_pred", "0")) == "1"
        lightweight_p3 = str(ai_info.get("ai_lightweight_p3_risk_pred", "0")) == "1"
        legacy = str(ai_info.get("ai_legacy_cadence_risk_pred", "0")) == "1"
        detector = str(ai_info.get("ai_detector_needed_pred", "0")) == "1"
        event_foreground = str(ai_info.get("ai_event_foreground_risk_pred", "0")) == "1"
        foreground_loss = str(ai_info.get("ai_foreground_loss_risk_pred", "0")) == "1"
        event_continuity = str(ai_info.get("ai_event_continuity_risk_pred", "0")) == "1"
        detector_refresh = str(ai_info.get("ai_detector_refresh_needed_for_event_pred", "0")) == "1"
        event_any = event_foreground or foreground_loss or event_continuity or detector_refresh
        active_event = self._float(telemetry.get("active_event_memory")) > 0
        video_name = str(telemetry.get("video", ""))
        is_ptz = str(telemetry.get("category", "")) == "PTZ"
        cubicle_like_named_context = "cubicle" in video_name.lower()
        cubicle_like_is_non_ptz_context = bool((not is_ptz) and video_name not in self.cubicle_like_exclude_videos)
        if not self.cubicle_like_requires_non_ptz:
            cubicle_like_is_non_ptz_context = bool(video_name not in self.cubicle_like_exclude_videos)
        camera_jump_motion = self._float(telemetry.get("camera_jump_suspect"))
        if cubicle_like_named_context and cubicle_like_is_non_ptz_context:
            camera_jump_motion = 0.0
        camera_motion_score = max(
            self._float(telemetry.get("continuous_pan_signature_active")),
            self._float(telemetry.get("position_switch_guard_active")),
            self._float(telemetry.get("position_switch_detector_burst_active")),
            self._float(telemetry.get("zoom_scale_suspect")),
            camera_jump_motion,
            self._float(telemetry.get("global_motion_escape_active")),
        )
        info["ai_cubicle_like_is_non_ptz_context"] = int(cubicle_like_is_non_ptz_context)
        info["ai_cubicle_like_camera_motion_score"] = float(camera_motion_score)
        event_score_high = self._float(ai_info.get("ai_event_foreground_risk_score"), 0.0) >= self.cubicle_like_event_score_threshold
        foreground_loss_score_high = self._float(ai_info.get("ai_foreground_loss_risk_score"), 0.0) >= self.cubicle_like_foreground_loss_threshold
        continuity_score_high = self._float(telemetry.get("gmq_event_continuity_risk"), 0.0) >= 0.65
        explicit_safety = any(
            self._float(telemetry.get(name)) > 0
            for name in [
                "closed_empty_blocked_final",
                "reuse_blocked_final",
                "lightweight_blocked_final",
                "ptz_closed_empty_kill_active",
                "closed_empty_blocked_under_ptz",
                "event_fn_risk_frames",
                "event_closed_empty_blocked_count",
            ]
        )
        pre_ai_event_state = str(telemetry.get("pre_ai_event_state", ""))
        pre_ai_known_event = pre_ai_event_state in {"TP", "FN"}
        current_event_state = str(telemetry.get("Event_State", ""))
        current_known_event = current_event_state in {"TP", "FN"}
        runtime_normal_frame = bool(not active_event and not explicit_safety and not pre_ai_known_event)
        micro_bump_score = max(
            self._float(ai_info.get("ai_event_foreground_risk_score"), 0.0),
            self._float(ai_info.get("ai_foreground_loss_risk_score"), 0.0),
            self._float(ai_info.get("ai_event_continuity_risk_score"), 0.0),
            min(1.0, self._float(telemetry.get("gmq_event_continuity_risk"), 0.0) + self._float(telemetry.get("foreground_risk"), 0.0)),
        )
        micro_bump_signal_ok = bool(
            micro_bump_score >= self.cubicle_micro_bump_score_threshold
            and (
                self._float(telemetry.get("gmq_event_continuity_risk"), 0.0) >= 0.65
                or self._float(ai_info.get("ai_foreground_loss_risk_score"), 0.0) >= self.cubicle_like_foreground_loss_threshold
                or self._float(ai_info.get("ai_event_foreground_risk_score"), 0.0) >= self.cubicle_micro_bump_score_threshold
            )
        )
        cubicle_like_action_candidate = bool(
            action_bucket in self.DETECTOR_ACTIONS
            or action_bucket == "LIGHTWEIGHT_MASK_ACC"
            or "P3_FALLBACK" in str(telemetry.get("action_label", "")).upper()
        )
        cubicle_like_pre_signal = bool(
            self.cubicle_like_event_continuity_enabled
            and cubicle_like_named_context
            and cubicle_like_is_non_ptz_context
            and active_event
            and camera_motion_score <= self.cubicle_like_max_camera_motion
            and cubicle_like_action_candidate
            and (event_score_high or foreground_loss_score_high or (continuity_score_high and self._float(telemetry.get("foreground_risk")) >= 0.20))
        )
        cubicle_micro_bump_pre_signal = bool(
            self.cubicle_micro_bump_enabled
            and cubicle_like_named_context
            and cubicle_like_is_non_ptz_context
            and (active_event or not self.cubicle_micro_bump_requires_active_memory)
            and (not runtime_normal_frame or not self.cubicle_micro_bump_requires_not_normal_frame)
            and camera_motion_score <= self.cubicle_like_max_camera_motion
            and micro_bump_signal_ok
        )
        frames_since_active_prediction = self._float(telemetry.get("frames_since_active_prediction"), 10**9)
        recent_event_memory = bool(0 <= frames_since_active_prediction <= 20)
        recent_event_memory_for_presignal = bool(
            active_event
            or (
                self.exact_cubicle_event_fn_pre_signal_recent_memory_min
                <= frames_since_active_prediction
                <= 20
            )
        )
        exact_cubicle_context = bool(
            str(telemetry.get("category", "")) == "shadow"
            and video_name == "cubicle"
        )
        exact_cubicle_stabilizer_memory_ok = bool(
            active_event
            or recent_event_memory
            or self._float(telemetry.get("gmq_event_continuity_risk"), 0.0) >= 0.20
        )
        exact_cubicle_stabilizer_score = max(
            self._float(ai_info.get("ai_event_foreground_risk_score"), 0.0),
            self._float(ai_info.get("ai_foreground_loss_risk_score"), 0.0),
            self._float(telemetry.get("foreground_risk"), 0.0),
        )
        exact_cubicle_stabilizer_unprotected_risk = bool(
            pre_ai_event_state == "FN"
            or current_event_state == "FN"
            or (
                current_known_event
                and exact_cubicle_stabilizer_score >= self.exact_cubicle_event_fn_stabilizer_foreground_loss_threshold
            )
            or self._float(telemetry.get("event_fn_risk_frames"), 0.0) > 0
            or self._float(telemetry.get("event_closed_empty_blocked_count"), 0.0) > 0
        )
        exact_cubicle_stabilizer_not_normal = bool(
            not runtime_normal_frame
            or current_known_event
            or (exact_cubicle_stabilizer_memory_ok and exact_cubicle_stabilizer_score >= self.exact_cubicle_event_fn_stabilizer_foreground_loss_threshold)
        )
        exact_cubicle_stabilizer_pre_signal = bool(
            self.exact_cubicle_event_fn_stabilizer_enabled
            and exact_cubicle_context
            and guard_active
            and (not self.exact_cubicle_event_fn_stabilizer_requires_non_ptz or not is_ptz)
            and exact_cubicle_stabilizer_memory_ok
            and exact_cubicle_stabilizer_not_normal
            and camera_motion_score <= self.cubicle_like_max_camera_motion
            and exact_cubicle_stabilizer_unprotected_risk
            and exact_cubicle_stabilizer_score >= self.exact_cubicle_event_fn_stabilizer_foreground_loss_threshold
        )
        exact_cubicle_empty_action = bool(
            action_bucket == "CLOSED_EMPTY"
            or "CLOSED_EMPTY" in str(telemetry.get("action_label", "")).upper()
        )
        action_text = str(telemetry.get("action_label", "")).upper()
        exact_cubicle_late_event_score = self._float(ai_info.get("ai_event_foreground_risk_score"), 0.0)
        exact_cubicle_late_foreground_loss_score = self._float(ai_info.get("ai_foreground_loss_risk_score"), 0.0)
        exact_cubicle_late_active_memory = self._float(telemetry.get("active_event_memory"), 0.0)
        exact_cubicle_late_action_ok = bool(
            action_text in self.exact_cubicle_late_event_rescue_actions
            or (
                action_bucket == "CLOSED_EMPTY"
                and "CLOSED_EMPTY" in action_text
                and ("FALLBACK" in action_text or action_text.endswith("_ACC"))
            )
        )
        exact_cubicle_late_score_ok = bool(
            exact_cubicle_late_event_score >= self.exact_cubicle_late_event_rescue_event_score_threshold
            or exact_cubicle_late_foreground_loss_score
            >= self.exact_cubicle_late_event_rescue_foreground_loss_threshold
        )
        exact_cubicle_late_global_motion_active = bool(
            self._float(telemetry.get("global_motion_escape_active"), 0.0) > 0
            or self._float(telemetry.get("gmq_event_hard_veto_active"), 0.0) > 0
            or self._float(telemetry.get("gmq_confirmed_camera_motion_allows_behavior"), 0.0) > 0
        )
        exact_cubicle_late_event_rescue_pre_signal = bool(
            self.exact_cubicle_late_event_rescue_enabled
            and exact_cubicle_context
            and guard_active
            and (
                not self.exact_cubicle_late_event_rescue_requires_active_memory
                or exact_cubicle_late_active_memory >= self.exact_cubicle_late_event_rescue_active_memory_min
            )
            and exact_cubicle_late_action_ok
            and exact_cubicle_late_score_ok
            and not is_ptz
            and not exact_cubicle_late_global_motion_active
            and camera_motion_score <= self.cubicle_like_max_camera_motion
        )
        if self.exact_cubicle_late_event_rescue_enabled:
            info["ai_exact_cubicle_late_event_rescue_frame"] = str(telemetry.get("raw_frame_id", ""))
            info["ai_exact_cubicle_late_event_rescue_action"] = str(telemetry.get("action_label", ""))
            info["ai_exact_cubicle_late_event_rescue_event_score"] = float(exact_cubicle_late_event_score)
            info["ai_exact_cubicle_late_event_rescue_foreground_loss_score"] = float(
                exact_cubicle_late_foreground_loss_score
            )
            info["ai_exact_cubicle_late_event_rescue_active_memory"] = float(exact_cubicle_late_active_memory)
        cubicle_live_mismatch_reuse_age = self._float(telemetry.get("reuse_age"), 10**9)
        cubicle_live_mismatch_action_ok = bool(
            action_text in self.cubicle_live_mismatch_reserve_actions
            or (
                action_bucket == "CLOSED_EMPTY"
                and "CLOSED_EMPTY" in action_text
                and ("FALLBACK" in action_text or action_text.endswith("_ACC"))
            )
        )
        cubicle_live_mismatch_score_ok = bool(
            exact_cubicle_late_event_score >= self.cubicle_live_mismatch_reserve_event_score_threshold
            or exact_cubicle_late_foreground_loss_score
            >= self.cubicle_live_mismatch_reserve_foreground_loss_threshold
        )
        cubicle_live_mismatch_reserve_pre_signal = bool(
            self.cubicle_live_mismatch_reserve_enabled
            and exact_cubicle_context
            and guard_active
            and cubicle_live_mismatch_action_ok
            and exact_cubicle_late_active_memory >= self.cubicle_live_mismatch_reserve_active_memory_min
            and cubicle_live_mismatch_reuse_age >= self.cubicle_live_mismatch_reserve_reuse_age_min
            and cubicle_live_mismatch_score_ok
            and not runtime_normal_frame
            and not is_ptz
            and not exact_cubicle_late_global_motion_active
            and camera_motion_score <= self.cubicle_like_max_camera_motion
        )
        if self.cubicle_live_mismatch_reserve_enabled:
            info["ai_cubicle_live_mismatch_reserve_frame"] = str(telemetry.get("raw_frame_id", ""))
        exact_cubicle_event_fn_pre_signal = bool(
            self.exact_cubicle_event_fn_pre_signal_enabled
            and exact_cubicle_context
            and guard_active
            and recent_event_memory_for_presignal
            and self._float(telemetry.get("foreground_risk"), 0.0)
            >= self.exact_cubicle_event_fn_pre_signal_foreground_risk_threshold
            and exact_cubicle_empty_action
            and not is_ptz
            and camera_motion_score <= self.cubicle_like_max_camera_motion
            and not detector
            and not detector_refresh
        )
        if self.exact_cubicle_event_fn_pre_signal_enabled:
            pre_signal_reasons = []
            if exact_cubicle_context:
                pre_signal_reasons.append("exact_shadow_cubicle")
            if guard_active:
                pre_signal_reasons.append("deterministic_guard")
            if active_event:
                pre_signal_reasons.append("active_event_memory")
            if recent_event_memory_for_presignal and not active_event:
                pre_signal_reasons.append("recent_event_memory")
            if self._float(telemetry.get("foreground_risk"), 0.0) >= self.exact_cubicle_event_fn_pre_signal_foreground_risk_threshold:
                pre_signal_reasons.append("foreground_risk")
            if current_event_state == "FN" or pre_ai_event_state == "FN":
                pre_signal_reasons.append("event_fn_risk")
            if exact_cubicle_empty_action:
                pre_signal_reasons.append("closed_empty_action")
            info["ai_exact_cubicle_event_fn_pre_signal"] = int(exact_cubicle_event_fn_pre_signal)
            info["ai_exact_cubicle_event_fn_pre_signal_reason"] = "+".join(dict.fromkeys(pre_signal_reasons))
            info["ai_exact_cubicle_event_fn_pre_signal_frame"] = str(telemetry.get("raw_frame_id", ""))
            info["ai_exact_cubicle_event_fn_pre_signal_action"] = str(telemetry.get("action_label", ""))
            info["ai_exact_cubicle_event_fn_pre_signal_recent_memory"] = int(frames_since_active_prediction)
            info["ai_exact_cubicle_event_fn_pre_signal_foreground_risk"] = self._float(telemetry.get("foreground_risk"), 0.0)
        current_video_key = f"{telemetry.get('category', '')}/{video_name}".replace("\\", "/")
        if (
            self.snowfall_carryover_gate_lock_enabled
            and current_video_key == self.snowfall_carryover_gate_lock_target_video
        ):
            info["ai_snowfall_carryover_gate_lock_status"] = (
                "active_reporting_lock"
                f"+proposal_le_{self.snowfall_carryover_gate_lock_max_proposal_rate:.3f}"
                f"+detector_le_{self.snowfall_carryover_gate_lock_max_detector_rate:.3f}"
                f"+unprotected_fn_le_{self.snowfall_carryover_gate_lock_max_unprotected_fn}"
            )
        if (
            self.lakeside_carryover_gate_lock_enabled
            and current_video_key == self.lakeside_carryover_gate_lock_target_video
        ):
            info["ai_lakeside_carryover_gate_lock_status"] = (
                "active_reporting_lock"
                f"+proposal_le_{self.lakeside_carryover_gate_lock_max_proposal_rate:.3f}"
                f"+detector_le_{self.lakeside_carryover_gate_lock_max_detector_rate:.3f}"
                f"+unprotected_fn_le_{self.lakeside_carryover_gate_lock_max_unprotected_fn}"
            )
        copymachine_context = bool(current_video_key == self.copymachine_shadow_target_video)
