        turbulence2_context = bool(current_video_key == self.turbulence2_target_video)
        turbulence2_event_score = self._float(ai_info.get("ai_event_foreground_risk_score"), 0.0)
        turbulence2_foreground_loss_score = self._float(ai_info.get("ai_foreground_loss_risk_score"), 0.0)
        turbulence2_continuity_score = max(
            self._float(ai_info.get("ai_event_continuity_risk_score"), 0.0),
            self._float(telemetry.get("gmq_event_continuity_risk"), 0.0),
        )
        turbulence2_localized_fn_risk = bool(
            current_event_state == "FN"
            or pre_ai_event_state == "FN"
            or self._float(telemetry.get("event_fn_risk_frames"), 0.0) > 0
            or self._float(telemetry.get("event_closed_empty_blocked_count"), 0.0) > 0
        )
        turbulence2_localized_event_risk = bool(
            turbulence2_localized_fn_risk
            or (
                active_event
                and (
                    turbulence2_event_score >= self.turbulence2_fn_rescue_event_score_threshold
                    or turbulence2_foreground_loss_score >= self.turbulence2_fn_rescue_foreground_loss_threshold
                    or turbulence2_continuity_score >= 0.65
                )
            )
        )
        turbulence2_unsafe_empty_or_fallback = bool(
            action_bucket == "CLOSED_EMPTY"
            or "CLOSED_EMPTY" in action_text
            or "FALLBACK" in action_text
        )
        turbulence2_not_normal_for_rescue = bool(
            not runtime_normal_frame
            or current_known_event
            or turbulence2_localized_event_risk
        )
        turbulence2_likely_unprotected_fn = bool(
            turbulence2_localized_fn_risk
            and turbulence2_unsafe_empty_or_fallback
        )
        turbulence2_score_ok = bool(
            turbulence2_event_score >= self.turbulence2_fn_rescue_event_score_threshold
            or turbulence2_foreground_loss_score >= self.turbulence2_fn_rescue_foreground_loss_threshold
            or turbulence2_likely_unprotected_fn
        )
        turbulence2_rescue_pre_signal = bool(
            self.turbulence2_fn_rescue_enabled
            and turbulence2_context
            and guard_active
            and (turbulence2_unsafe_empty_or_fallback or turbulence2_likely_unprotected_fn)
            and turbulence2_score_ok
            and (
                not self.turbulence2_fn_rescue_requires_localized_risk
                or turbulence2_localized_event_risk
            )
            and (
                not self.turbulence2_fn_rescue_requires_not_normal_frame
                or turbulence2_not_normal_for_rescue
            )
            and (
                not self.turbulence2_fn_rescue_protect_likely_unprotected_fn
                or turbulence2_likely_unprotected_fn
            )
            and not is_ptz
        )
        if self.turbulence2_fn_rescue_enabled:
            info["ai_turbulence2_fn_rescue_candidate"] = int(turbulence2_rescue_pre_signal)
            info["ai_turbulence2_fn_rescue_frame"] = str(telemetry.get("raw_frame_id", ""))
        if self.turbulence2_carryover_reserve_enabled:
            info["ai_turbulence2_carryover_reserve_frame"] = str(telemetry.get("raw_frame_id", ""))
        thermal_lakeside_context = bool(current_video_key == self.thermal_lakeside_target_video)
        thermal_lakeside_event_score = self._float(ai_info.get("ai_event_foreground_risk_score"), 0.0)
        thermal_lakeside_foreground_loss_score = self._float(
            ai_info.get("ai_foreground_loss_risk_score"),
            0.0,
        )
        thermal_lakeside_foreground_risk = self._float(telemetry.get("foreground_risk"), 0.0)
        thermal_lakeside_active_memory = self._float(telemetry.get("active_event_memory"), 0.0)
        thermal_lakeside_action_ok = bool(
            action_text in self.thermal_lakeside_fn_rescue_actions
            or (
                action_bucket == "CLOSED_EMPTY"
                and "CLOSED_EMPTY" in action_text
                and ("FALLBACK" in action_text or action_text.endswith("_ACC"))
            )
        )
        thermal_lakeside_score_ok = bool(
            thermal_lakeside_event_score >= self.thermal_lakeside_fn_rescue_event_score_threshold
            or thermal_lakeside_foreground_loss_score
            >= self.thermal_lakeside_fn_rescue_foreground_loss_threshold
            or thermal_lakeside_foreground_risk
            >= self.thermal_lakeside_fn_rescue_foreground_risk_threshold
        )
        thermal_lakeside_not_normal_for_rescue = bool(
            not runtime_normal_frame
            or current_known_event
            or (
                thermal_lakeside_active_memory >= self.thermal_lakeside_fn_rescue_active_memory_min
                and thermal_lakeside_score_ok
            )
        )
        thermal_lakeside_cap_or_budget_exhausted = bool(
            self._budget_remaining("non_cubicle_event_fg") <= 0
            or self._budget_remaining("closed_empty") <= 0
            or info["ai_intervention_budget_blocked"]
        )
        thermal_lakeside_fn_rescue_pre_signal = bool(
            self.thermal_lakeside_fn_rescue_enabled
            and thermal_lakeside_context
            and guard_active
            and thermal_lakeside_action_ok
            and thermal_lakeside_score_ok
            and (
                not self.thermal_lakeside_fn_rescue_requires_active_memory
                or thermal_lakeside_active_memory
                >= self.thermal_lakeside_fn_rescue_active_memory_min
            )
            and (
                not self.thermal_lakeside_fn_rescue_requires_not_normal_frame
                or thermal_lakeside_not_normal_for_rescue
            )
            and (
                not self.thermal_lakeside_fn_rescue_requires_cap_exhausted_or_closed_empty_budget
                or thermal_lakeside_cap_or_budget_exhausted
            )
            and not is_ptz
        )
        thermal_lakeside_early_action_ok = bool(
            action_text in self.thermal_lakeside_early_memory_rescue_actions
            or (
                action_bucket == "CLOSED_EMPTY"
                and "CLOSED_EMPTY" in action_text
                and ("FALLBACK" in action_text or action_text.endswith("_ACC"))
            )
        )
        thermal_lakeside_early_age_ok = bool(
            self.thermal_lakeside_early_memory_rescue_recent_age_min
            <= frames_since_active_prediction
            <= self.thermal_lakeside_early_memory_rescue_recent_age_max
        )
        thermal_lakeside_early_not_normal = bool(not runtime_normal_frame or current_known_event)
        thermal_lakeside_early_memory_rescue_pre_signal = bool(
            self.thermal_lakeside_early_memory_rescue_enabled
            and thermal_lakeside_context
            and guard_active
            and thermal_lakeside_early_action_ok
            and thermal_lakeside_active_memory >= 1
            and thermal_lakeside_early_age_ok
            and (
                not self.thermal_lakeside_early_memory_rescue_requires_not_normal_frame
                or thermal_lakeside_early_not_normal
            )
            and not is_ptz
        )
        if self.thermal_lakeside_fn_rescue_enabled:
            info["ai_thermal_lakeside_fn_rescue_candidate"] = int(
                thermal_lakeside_fn_rescue_pre_signal
            )
            info["ai_thermal_lakeside_fn_rescue_frame"] = str(telemetry.get("raw_frame_id", ""))
        if self.thermal_lakeside_early_memory_rescue_enabled:
            info["ai_thermal_lakeside_early_memory_rescue_candidate"] = int(
                thermal_lakeside_early_memory_rescue_pre_signal
            )
        tunnel_exit_lf_context = bool(current_video_key == self.tunnel_exit_lf_target_video)
        tunnel_exit_lf_event_score = self._float(ai_info.get("ai_event_foreground_risk_score"), 0.0)
        tunnel_exit_lf_foreground_loss_score = self._float(ai_info.get("ai_foreground_loss_risk_score"), 0.0)
        tunnel_exit_lf_continuity_score = max(
            self._float(ai_info.get("ai_event_continuity_risk_score"), 0.0),
            self._float(telemetry.get("gmq_event_continuity_risk"), 0.0),
        )
        tunnel_exit_lf_persistence_score = max(
            self._float(telemetry.get("foreground_risk"), 0.0),
            tunnel_exit_lf_continuity_score,
            self._float(telemetry.get("active_event_memory"), 0.0),
        )
        tunnel_exit_lf_recent_memory = bool(
            active_event
            or recent_event_memory
            or 0 <= frames_since_active_prediction <= max(20, self.tunnel_exit_lf_recent_memory_min)
            or self._float(telemetry.get("frames_since_last_active_prediction"), 10**9)
            <= max(20, self.tunnel_exit_lf_recent_memory_min)
        )
        tunnel_exit_lf_localized_fn_risk = bool(
            current_event_state == "FN"
            or pre_ai_event_state == "FN"
            or self._float(telemetry.get("event_fn_risk_frames"), 0.0) > 0
            or self._float(telemetry.get("event_closed_empty_blocked_count"), 0.0) > 0
        )
        tunnel_exit_lf_score_ok = bool(
            tunnel_exit_lf_event_score >= self.tunnel_exit_lf_rescue_event_score_threshold
            or tunnel_exit_lf_foreground_loss_score >= self.tunnel_exit_lf_rescue_foreground_loss_threshold
            or tunnel_exit_lf_persistence_score >= self.tunnel_exit_lf_persistence_threshold
            or tunnel_exit_lf_localized_fn_risk
        )
        tunnel_exit_lf_localized_event_risk = bool(
            tunnel_exit_lf_localized_fn_risk
            or (
                tunnel_exit_lf_recent_memory
                and tunnel_exit_lf_score_ok
            )
        )
        tunnel_exit_lf_unsafe_empty_or_fallback = bool(
            action_bucket == "CLOSED_EMPTY"
            or "CLOSED_EMPTY" in action_text
            or "FALLBACK" in action_text
        )
        tunnel_exit_lf_not_normal_for_rescue = bool(
            not runtime_normal_frame
            or current_known_event
            or tunnel_exit_lf_localized_event_risk
        )
        tunnel_exit_lf_likely_unprotected_fn = bool(
            tunnel_exit_lf_localized_fn_risk
            and tunnel_exit_lf_unsafe_empty_or_fallback
        )
        tunnel_exit_lf_rescue_pre_signal = bool(
            self.tunnel_exit_lf_rescue_enabled
            and tunnel_exit_lf_context
            and guard_active
            and (tunnel_exit_lf_unsafe_empty_or_fallback or tunnel_exit_lf_likely_unprotected_fn)
            and tunnel_exit_lf_score_ok
            and (
                not self.tunnel_exit_lf_rescue_requires_localized_risk
                or tunnel_exit_lf_localized_event_risk
            )
            and (
                not self.tunnel_exit_lf_rescue_requires_not_normal_frame
                or tunnel_exit_lf_not_normal_for_rescue
            )
            and (
                not self.tunnel_exit_lf_rescue_prioritize_likely_unprotected_fn
                or tunnel_exit_lf_likely_unprotected_fn
            )
            and not is_ptz
        )
        if self.tunnel_exit_lf_rescue_enabled:
            info["ai_tunnel_exit_lf_rescue_candidate"] = int(tunnel_exit_lf_rescue_pre_signal)
        port_lf_holdout_context = bool(
            self.port_lf_post_suppression_holdout_enabled
            and current_video_key == self.port_lf_post_suppression_holdout_target_video
        )
        port_lf_holdout_action_ok = bool(
            action_text in self.port_lf_post_suppression_holdout_actions
            or (
                action_bucket == "CLOSED_EMPTY"
                and "CLOSED_EMPTY" in action_text
                and ("FALLBACK" in action_text or action_text.endswith("_ACC"))
            )
        )
        port_lf_holdout_event_score = self._float(ai_info.get("ai_event_foreground_risk_score"), 0.0)
        port_lf_holdout_foreground_loss = self._float(ai_info.get("ai_foreground_loss_risk_score"), 0.0)
        port_lf_holdout_foreground_risk = self._float(telemetry.get("foreground_risk"), 0.0)
        port_lf_holdout_recent_suppression_raw = bool(
            0
            <= current_raw_frame_id_for_signal
            - int(self.last_port_lf_detector_retighten_v4_suppressed_raw_frame_id)
            <= max(1, self.port_lf_post_suppression_holdout_window) * 5
        )
        port_lf_holdout_risk_signal = bool(
            active_event
            or recent_event_memory
            or current_event_state == "FN"
            or pre_ai_event_state == "FN"
            or port_lf_holdout_event_score >= self.port_lf_post_suppression_holdout_event_score_threshold
            or port_lf_holdout_foreground_loss
            >= self.port_lf_post_suppression_holdout_foreground_loss_threshold
            or port_lf_holdout_foreground_risk
            >= self.port_lf_post_suppression_holdout_foreground_risk_threshold
        )
        port_lf_holdout_not_normal = bool(
            not runtime_normal_frame
            or current_known_event
            or port_lf_holdout_risk_signal
        )
        port_lf_holdout_pre_signal = bool(
            port_lf_holdout_context
            and guard_active
            and port_lf_holdout_recent_suppression_raw
            and port_lf_holdout_action_ok
            and port_lf_holdout_risk_signal
            and (
                not self.port_lf_post_suppression_holdout_requires_not_normal_frame
                or port_lf_holdout_not_normal
            )
        )
        ptz_live_mismatch_context = bool(current_video_key == self.ptz_intermittent_pan_target_video)
        ptz_live_mismatch_event_score = self._float(ai_info.get("ai_event_foreground_risk_score"), 0.0)
        ptz_live_mismatch_foreground_risk = self._float(telemetry.get("foreground_risk"), 0.0)
        ptz_live_mismatch_reuse_age = self._float(telemetry.get("reuse_age"), 10**9)
        ptz_live_mismatch_action_ok = bool(
            action_text in self.ptz_intermittent_pan_live_mismatch_rescue_actions
            or (
                action_bucket == "CLOSED_EMPTY"
                and "CLOSED_EMPTY" in action_text
                and ("FALLBACK" in action_text or action_text.endswith("_ACC"))
            )
        )
        ptz_live_mismatch_global_or_localized = bool(
            ptz_live_mismatch_foreground_risk >= self.ptz_intermittent_pan_live_mismatch_rescue_foreground_risk_threshold
            or (
                active_event
                and (
                    camera_motion_score > 0
                    or self._float(telemetry.get("gmq_confirmed_camera_motion_allows_behavior"), 0.0) > 0
                    or self._float(telemetry.get("gmq_global_motion_risk"), 0.0) >= 0.65
                    or current_event_state == "FN"
                    or pre_ai_event_state == "FN"
                )
            )
        )
        ptz_live_mismatch_rescue_pre_signal = bool(
            self.ptz_intermittent_pan_live_mismatch_rescue_enabled
            and ptz_live_mismatch_context
            and guard_active
            and ptz_live_mismatch_action_ok
            and active_event
            and self._float(telemetry.get("active_event_memory"), 0.0)
            >= self.ptz_intermittent_pan_live_mismatch_rescue_active_memory_min
            and ptz_live_mismatch_reuse_age >= self.ptz_intermittent_pan_live_mismatch_rescue_reuse_age_min
            and ptz_live_mismatch_event_score >= self.ptz_intermittent_pan_live_mismatch_rescue_event_score_threshold
            and ptz_live_mismatch_global_or_localized
            and not runtime_normal_frame
            and is_ptz
        )
        if self.ptz_intermittent_pan_live_mismatch_rescue_enabled:
            info["ai_ptz_intermittent_pan_live_mismatch_rescue_frame"] = str(telemetry.get("raw_frame_id", ""))
        high = bool(
            closed
            or reuse
            or lightweight_p3
            or legacy
            or detector
            or event_any
            or cubicle_like_pre_signal
            or cubicle_micro_bump_pre_signal
            or exact_cubicle_stabilizer_pre_signal
            or exact_cubicle_event_fn_pre_signal
            or exact_cubicle_late_event_rescue_pre_signal
            or cubicle_live_mismatch_reserve_pre_signal
            or ptz_live_mismatch_rescue_pre_signal
            or copymachine_rescue_pre_signal
            or copymachine_rescue_first_pre_signal
            or copymachine_live_cap_reserve_pre_signal
            or parking_iom_rescue_pre_signal
            or parking_restore_4d6_fn_fallback_pre_signal
            or parking_4d6_hard_restore_pre_signal
            or sofa_iom_rescue_pre_signal
            or snowfall_weather_rescue_pre_signal
            or snowfall_actual_fn_rescue_pre_signal
            or parking_live_cap_reserve_pre_signal
            or parking_live_burst_bridge_pre_signal
            or turbulence2_rescue_pre_signal
            or thermal_lakeside_fn_rescue_pre_signal
            or thermal_lakeside_early_memory_rescue_pre_signal
            or tunnel_exit_lf_rescue_pre_signal
            or port_lf_holdout_pre_signal
        )
        info["ai_intervention_risk_high"] = int(high)
        if high and self.intervention_require_guard and not guard_active:
            info["ai_intervention_blocked_no_guard"] = 1
            return self._apply_q1_sic_detector_action_probe(info, telemetry, ai_info)
        if not high or (self.intervention_require_guard and not guard_active):
            return self._apply_q1_sic_detector_action_probe(info, telemetry, ai_info)

        evaluated_index = int(self._float(telemetry.get("evaluated_index"), 0.0))
        consumed_budgets = []
        previous_last_ai_detector_eval_index = int(self.last_ai_detector_eval_index)
        previous_last_cubicle_like_raw_frame_id = int(self.last_cubicle_like_raw_frame_id)
        previous_last_cubicle_micro_bump_raw_frame_id = int(self.last_cubicle_micro_bump_raw_frame_id)
        previous_last_exact_cubicle_event_fn_stabilizer_raw_frame_id = int(
            self.last_exact_cubicle_event_fn_stabilizer_raw_frame_id
        )
        previous_last_exact_cubicle_late_event_rescue_raw_frame_id = int(
            self.last_exact_cubicle_late_event_rescue_raw_frame_id
        )
        previous_last_cubicle_live_mismatch_reserve_raw_frame_id = int(
            self.last_cubicle_live_mismatch_reserve_raw_frame_id
        )
        previous_last_ptz_intermittent_pan_fn_rescue_raw_frame_id = int(
            self.last_ptz_intermittent_pan_fn_rescue_raw_frame_id
        )
        previous_last_ptz_intermittent_pan_live_mismatch_rescue_raw_frame_id = int(
            self.last_ptz_intermittent_pan_live_mismatch_rescue_raw_frame_id
        )
        previous_last_copymachine_fn_rescue_raw_frame_id = int(
            self.last_copymachine_fn_rescue_raw_frame_id
        )
        previous_last_copymachine_live_cap_reserve_raw_frame_id = int(
            self.last_copymachine_live_cap_reserve_raw_frame_id
        )
        previous_last_parking_iom_rescue_raw_frame_id = int(
            self.last_parking_iom_rescue_raw_frame_id
        )
        previous_last_sofa_iom_rescue_raw_frame_id = int(
            self.last_sofa_iom_rescue_raw_frame_id
        )
        previous_last_snowfall_weather_rescue_raw_frame_id = int(
            self.last_snowfall_weather_rescue_raw_frame_id
        )
        previous_last_parking_live_cap_reserve_raw_frame_id = int(
            self.last_parking_live_cap_reserve_raw_frame_id
        )
        previous_last_parking_live_burst_bridge_raw_frame_id = int(
            self.last_parking_live_burst_bridge_raw_frame_id
        )
        previous_last_parking_live_preserve_or_rescue_raw_frame_id = int(
            self.last_parking_live_preserve_or_rescue_raw_frame_id
        )
        previous_last_turbulence2_fn_rescue_raw_frame_id = int(
            self.last_turbulence2_fn_rescue_raw_frame_id
        )
        previous_last_turbulence2_carryover_reserve_raw_frame_id = int(
            self.last_turbulence2_carryover_reserve_raw_frame_id
        )
        previous_last_thermal_lakeside_fn_rescue_raw_frame_id = int(
            self.last_thermal_lakeside_fn_rescue_raw_frame_id
        )
        previous_last_thermal_lakeside_early_memory_rescue_raw_frame_id = int(
            self.last_thermal_lakeside_early_memory_rescue_raw_frame_id
        )
        previous_last_tunnel_exit_lf_rescue_raw_frame_id = int(
            self.last_tunnel_exit_lf_rescue_raw_frame_id
        )
        previous_last_port_lf_detector_retighten_v4_suppressed_raw_frame_id = int(
            self.last_port_lf_detector_retighten_v4_suppressed_raw_frame_id
        )
        previous_last_port_lf_detector_retighten_v4_suppressed_eval_index = int(
            self.last_port_lf_detector_retighten_v4_suppressed_eval_index
        )
        previous_last_port_lf_post_suppression_holdout_raw_frame_id = int(
            self.last_port_lf_post_suppression_holdout_raw_frame_id
        )

        def consume_budget(name):
            self._consume_budget(name)
            consumed_budgets.append(name)

        def refund_frame_budgets():
            for name in reversed(consumed_budgets):
                self._refund_budget(name)
            consumed_budgets.clear()

        def remove_detector_request_from_current_proposal():
            nonlocal kinds
            if not info["ai_intervention_detector_requested"]:
                return
            if "detector" in consumed_budgets:
                consumed_budgets.remove("detector")
                self._refund_budget("detector")
            kinds = [kind for kind in kinds if kind != "request_detector"]
            self.last_ai_detector_eval_index = previous_last_ai_detector_eval_index
            info["ai_intervention_detector_requested"] = 0
            info["ai_detector_last_resort_used"] = 0
            info["ai_detector_request_source"] = ""
            info["ai_detector_request_blocked_interval"] = 0
            info["ai_detector_request_blocked_budget"] = 0
            info["ai_detector_request_event_refresh_specific"] = 0

        event_budget_available = self._budget_remaining("event") > 0
        ptz_budget_available = (not is_ptz) or self._budget_remaining("ptz") > 0
        if (
            not event_budget_available
            and not cubicle_like_pre_signal
            and not cubicle_micro_bump_pre_signal
            and not exact_cubicle_stabilizer_pre_signal
            and not exact_cubicle_late_event_rescue_pre_signal
            and not cubicle_live_mismatch_reserve_pre_signal
            and not ptz_live_mismatch_rescue_pre_signal
            and not copymachine_rescue_pre_signal
            and not copymachine_rescue_first_pre_signal
            and not copymachine_live_cap_reserve_pre_signal
            and not parking_iom_rescue_pre_signal
            and not sofa_iom_rescue_pre_signal
            and not snowfall_weather_rescue_pre_signal
            and not snowfall_actual_fn_rescue_pre_signal
            and not parking_live_cap_reserve_pre_signal
            and not parking_live_burst_bridge_pre_signal
            and not turbulence2_rescue_pre_signal
            and not thermal_lakeside_fn_rescue_pre_signal
            and not thermal_lakeside_early_memory_rescue_pre_signal
            and not port_lf_holdout_pre_signal
        ):
            info["ai_intervention_budget_blocked"] = 1
            return self._apply_q1_sic_detector_action_probe(info, telemetry, ai_info)
        if not ptz_budget_available:
            info["ai_intervention_budget_blocked"] = 1
            return self._apply_q1_sic_detector_action_probe(info, telemetry, ai_info)

        kinds = []
        foreground_risk_high = self._float(telemetry.get("foreground_risk")) >= 0.55
        event_fg_score_reasons = []
        for target, label in [
            ("ai_event_foreground_risk_score", "event_foreground_risk"),
            ("ai_foreground_loss_risk_score", "foreground_loss_risk"),
            ("ai_event_continuity_risk_score", "event_continuity_risk"),
        ]:
            if self._float(ai_info.get(target), 0.0) >= self.event_foreground_block_only_threshold:
                event_fg_score_reasons.append(label)
        event_fg_pred_reasons = []
        if event_foreground:
            event_fg_pred_reasons.append("event_foreground_risk")
        if foreground_loss:
            event_fg_pred_reasons.append("foreground_loss_risk")
        if event_continuity:
            event_fg_pred_reasons.append("event_continuity_risk")
        event_fg_risk_high = bool(event_fg_score_reasons)
        if not event_fg_score_reasons and self.event_foreground_block_only_threshold <= 0.0:
            event_fg_risk_high = bool(event_fg_pred_reasons)
        event_fg_memory_ok = bool(active_event or foreground_risk_high)
        event_fg_block_only_active = bool(
            self.event_foreground_block_only_override_enabled
            and guard_active
            and event_fg_risk_high
            and (event_fg_memory_ok or not self.event_foreground_requires_active_memory)
        )
        if event_fg_block_only_active:
            reason_parts = list(dict.fromkeys(event_fg_score_reasons or event_fg_pred_reasons))
            if active_event:
                reason_parts.append("active_event_memory")
            if foreground_risk_high:
                reason_parts.append("foreground_risk")
            info["ai_event_foreground_block_only_active"] = 1
            info["ai_event_foreground_block_only_reason"] = "+".join(reason_parts)
        explicit_safety = any(
            self._float(telemetry.get(name)) > 0
            for name in [
                "closed_empty_blocked_final",
                "reuse_blocked_final",
                "lightweight_blocked_final",
                "ptz_closed_empty_kill_active",
                "closed_empty_blocked_under_ptz",
                "event_fn_risk_frames",
                "event_closed_empty_blocked_count",
            ]
        )
        strong_event_context = bool(active_event or foreground_loss or detector_refresh or explicit_safety)
        if self.non_cubicle_budget_reclaim_enabled and event_fg_block_only_active:
            non_cubicle_candidate = not (self.non_cubicle_event_fg_exclude_cubicle and cubicle_like_named_context)
            if non_cubicle_candidate:
                info["ai_non_cubicle_budget_reclaim_active"] = 1
                info["ai_non_cubicle_event_fg_would_have_proposed_before_reclaim"] = 1
                action_would_be_blocked_without_event_fg = bool(
                    (action_bucket == "CLOSED_EMPTY" and closed and strong_event_context)
                    or (action_bucket == "REUSE_ACC" and reuse and strong_event_context)
                    or (action_bucket == "LIGHTWEIGHT_MASK_P3_FALLBACK" and lightweight_p3 and strong_event_context)
                    or (action_bucket == "LEGACY_SAFE_P3_GUARD" and legacy and strong_event_context)
                )
                score_ok = bool(
                    max(
                        self._float(ai_info.get("ai_event_foreground_risk_score"), 0.0),
                        self._float(ai_info.get("ai_foreground_loss_risk_score"), 0.0),
                    )
                    >= self.non_cubicle_event_fg_min_score
                )
                continuity_ok = bool(
                    not self.non_cubicle_event_fg_require_continuity
                    or event_continuity
                    or self._float(telemetry.get("gmq_event_continuity_risk"), 0.0) >= 0.65
                )
                fn_risk_ok = bool(
                    not self.non_cubicle_event_fg_require_unprotected_fn_risk
                    or self._float(telemetry.get("event_fn_risk_frames"), 0.0) > 0
                    or self._float(telemetry.get("event_closed_empty_blocked_count"), 0.0) > 0
                )
                non_ptz_motion_ok = bool((not is_ptz) and camera_motion_score <= self.cubicle_like_max_camera_motion)
                strict_preserve = bool(active_event and score_ok and continuity_ok and fn_risk_ok and non_ptz_motion_ok)
                protect_bridge = bool(
                    self.non_cubicle_event_fg_protect_bridge_entry
                    and video_name == "bridgeEntry"
                )
                continuous_pan_max_frames = int(round(self.non_cubicle_event_fg_protect_continuous_pan_max_rate * 100.0))
                protect_continuous_pan = bool(
                    video_name == "continuousPan"
                    and int(self.budget_counts.get("non_cubicle_event_fg_preserved", 0)) < max(0, continuous_pan_max_frames)
                )
                reclaim_cap_remaining = (
                    int(self.budget_counts.get("non_cubicle_event_fg_reclaimed", 0))
                    < self.non_cubicle_event_fg_reclaim_target_per_video
                )
                cap_available = self._budget_remaining("non_cubicle_event_fg") > 0
                reclaim_reasons = []
                if protect_bridge:
                    reclaim_reasons.append("bridge_entry_protected")
                if protect_continuous_pan:
                    reclaim_reasons.append("continuous_pan_rate_protected")
                if strict_preserve:
                    reclaim_reasons.append("strict_event_fn_risk_preserved")
                if action_would_be_blocked_without_event_fg:
                    reclaim_reasons.append("subrisk_block_preserved")
                if not cap_available:
                    reclaim_reasons.append("event_fg_cap_exhausted")
                if not reclaim_cap_remaining:
                    reclaim_reasons.append("reduction_target_satisfied")
                should_reclaim = bool(
                    cap_available
                    and reclaim_cap_remaining
                    and not protect_bridge
                    and not protect_continuous_pan
                    and not strict_preserve
                    and not action_would_be_blocked_without_event_fg
                )
                if should_reclaim:
                    event_fg_block_only_active = False
                    info["ai_event_foreground_block_only_active"] = 0
                    info["ai_event_foreground_block_only_reason"] = ""
                    info["ai_non_cubicle_budget_reclaim_rejected"] = 1
                    info["ai_non_cubicle_budget_reclaim_reason"] = "reclaimed_non_cubicle_event_foreground_only"
                    consume_budget("non_cubicle_event_fg_reclaimed")
                else:
                    if not reclaim_reasons:
                        reclaim_reasons.append("preserved_by_reclaim_policy")
                    info["ai_non_cubicle_budget_reclaim_reason"] = "+".join(dict.fromkeys(reclaim_reasons))
                    consume_budget("non_cubicle_event_fg_preserved")
                if cap_available:
                    consume_budget("non_cubicle_event_fg")
                info["ai_non_cubicle_event_fg_cap_used"] = int(self.budget_counts.get("non_cubicle_event_fg", 0))
                info["ai_non_cubicle_event_fg_reclaimed_count"] = int(self.budget_counts.get("non_cubicle_event_fg_reclaimed", 0))
                info["ai_non_cubicle_event_fg_preserved_count"] = int(self.budget_counts.get("non_cubicle_event_fg_preserved", 0))
        if (
            self.intervention_normal_frame_suppressor
            and guard_active
            and not active_event
            and not foreground_loss
            and not detector_refresh
            and not closed
            and not explicit_safety
            and not event_fg_block_only_active
        ):
            info["ai_normal_frame_suppressor_active"] = 1
            info["ai_normal_frame_suppressor_reason"] = "no_active_event_no_foreground_loss_no_refresh_no_closed_empty"
            if (
                exact_cubicle_event_fn_pre_signal
                and self.exact_cubicle_event_fn_pre_signal_bypass_early_normal_only
            ):
                info["ai_exact_cubicle_event_fn_pre_signal_bypassed_early_normal"] = 1
                info["ai_normal_frame_suppressor_reason"] = (
                    "bypassed_by_exact_cubicle_event_fn_pre_signal"
                )
            else:
                return self._apply_q1_sic_detector_action_probe(info, telemetry, ai_info)

        detector_blocked_for_refresh = False
        if action_bucket == "CLOSED_EMPTY" and (closed or (event_foreground and strong_event_context) or event_fg_block_only_active):
            if self.intervention_allow_closed_empty_block and self._budget_remaining("closed_empty") > 0:
                consume_budget("closed_empty")
                info["ai_intervention_closed_empty_blocked"] = 1
                info["ai_safe_replacement_source"] = "existing_final_sanitizer_or_deterministic_fallback"
                kinds.append("block_closed_empty")
                if event_fg_block_only_active:
                    info["ai_event_foreground_safe_replacement_source"] = info["ai_safe_replacement_source"]
            else:
                info["ai_intervention_budget_blocked"] = 1
        if action_bucket == "REUSE_ACC" and ((reuse and strong_event_context) or event_fg_block_only_active):
            if self.intervention_allow_reuse_block and self._budget_remaining("reuse") > 0:
                consume_budget("reuse")
                info["ai_intervention_reuse_blocked"] = 1
                info["ai_safe_replacement_source"] = "existing_guarded_reuse_fallback_or_detector_last_resort"
                kinds.append("block_reuse")
                if event_fg_block_only_active:
                    info["ai_event_foreground_safe_replacement_source"] = info["ai_safe_replacement_source"]
            else:
                info["ai_intervention_budget_blocked"] = 1
        if action_bucket == "LIGHTWEIGHT_MASK_P3_FALLBACK" and ((lightweight_p3 and strong_event_context) or event_fg_block_only_active):
            if self.intervention_allow_lightweight_p3_block and self._budget_remaining("lightweight") > 0:
                consume_budget("lightweight")
                info["ai_intervention_lightweight_blocked"] = 1
                info["ai_safe_replacement_source"] = "fallback_p3_guard"
                kinds.append("block_lightweight_p3")
                if event_fg_block_only_active:
                    info["ai_event_foreground_safe_replacement_source"] = info["ai_safe_replacement_source"]
            else:
                info["ai_intervention_budget_blocked"] = 1
        if action_bucket == "LEGACY_SAFE_P3_GUARD" and legacy and strong_event_context:
            info["ai_intervention_legacy_blocked"] = 1
            info["ai_safe_replacement_source"] = "existing_legacy_guard"
            kinds.append("block_legacy_cadence")

        raw_frame_id = int(self._float(telemetry.get("raw_frame_id"), evaluated_index))
        cubicle_like_active = False
        if self.cubicle_like_event_continuity_enabled:
            cooldown_remaining = max(0, self.cubicle_like_proposal_cooldown - (raw_frame_id - int(self.last_cubicle_like_raw_frame_id)))
            cubicle_like_reason_parts = []
            if event_score_high:
                cubicle_like_reason_parts.append("event_foreground_score")
            if foreground_loss_score_high:
                cubicle_like_reason_parts.append("foreground_loss_score")
            if continuity_score_high:
                cubicle_like_reason_parts.append("event_continuity")
            if event_fg_block_only_active:
                cubicle_like_reason_parts.append("event_foreground_block_only_context")
            if active_event:
                cubicle_like_reason_parts.append("active_event_memory")
            if self._float(telemetry.get("foreground_risk")) >= 0.20:
                cubicle_like_reason_parts.append("foreground_risk")
            cubicle_like_signal_ok = bool(
                event_score_high
                or foreground_loss_score_high
                or (continuity_score_high and self._float(telemetry.get("foreground_risk")) >= 0.20)
                or (cubicle_like_named_context and active_event and event_fg_block_only_active)
            )
            if kinds:
                info["ai_cubicle_like_rejected_reason"] = "already_protected"
            elif not cubicle_like_named_context:
                info["ai_cubicle_like_rejected_reason"] = "not_cubicle_like_video"
            elif not cubicle_like_is_non_ptz_context:
                info["ai_cubicle_like_rejected_reason"] = "not_non_ptz_context"
            elif self.cubicle_like_requires_active_memory and not active_event:
                info["ai_cubicle_like_rejected_reason"] = "missing_active_event_memory"
            elif camera_motion_score > self.cubicle_like_max_camera_motion:
                info["ai_cubicle_like_rejected_reason"] = "camera_motion_context"
            elif not cubicle_like_action_candidate:
                info["ai_cubicle_like_rejected_reason"] = "action_not_detector_or_fallback"
            elif not cubicle_like_signal_ok:
                info["ai_cubicle_like_rejected_reason"] = "event_continuity_signal_low"
            elif self._budget_remaining("cubicle_like") <= 0:
                info["ai_cubicle_like_rejected_reason"] = "proposal_cap_exhausted"
                info["ai_intervention_budget_blocked"] = 1
            elif cooldown_remaining > 0:
                info["ai_cubicle_like_rejected_reason"] = "proposal_cooldown"
            else:
                cubicle_like_active = True
                consume_budget("cubicle_like")
                self.last_cubicle_like_raw_frame_id = raw_frame_id
                info["ai_cubicle_like_event_continuity_active"] = 1
                info["ai_cubicle_like_event_continuity_reason"] = "+".join(dict.fromkeys(cubicle_like_reason_parts))
                info["ai_cubicle_like_no_detector"] = 1
                info["ai_cubicle_like_safe_replacement_source"] = "existing_deterministic_no_detector_fallback"
                info["ai_safe_replacement_source"] = "existing_deterministic_no_detector_fallback"
                kinds.append("cubicle_like_event_continuity_no_detector_fallback")
            info["ai_cubicle_like_cap_used"] = int(self.budget_counts.get("cubicle_like", 0))

        cubicle_micro_bump_active = False
        if self.cubicle_micro_bump_enabled:
            cooldown_remaining = max(
                0,
                self.cubicle_micro_bump_cooldown - (raw_frame_id - int(self.last_cubicle_micro_bump_raw_frame_id)),
            )
            micro_reason_parts = []
            if micro_bump_score >= self.cubicle_micro_bump_score_threshold:
                micro_reason_parts.append("micro_score")
            if self._float(telemetry.get("gmq_event_continuity_risk"), 0.0) >= 0.65:
                micro_reason_parts.append("event_continuity")
            if self._float(ai_info.get("ai_foreground_loss_risk_score"), 0.0) >= self.cubicle_like_foreground_loss_threshold:
                micro_reason_parts.append("foreground_loss_score")
            if active_event:
                micro_reason_parts.append("active_event_memory")
            if pre_ai_known_event:
                micro_reason_parts.append("pre_ai_known_event")
            if kinds:
                info["ai_cubicle_micro_bump_rejected_reason"] = "already_protected"
            elif not cubicle_like_named_context:
                info["ai_cubicle_micro_bump_rejected_reason"] = "not_cubicle_like_video"
            elif not cubicle_like_is_non_ptz_context:
                info["ai_cubicle_micro_bump_rejected_reason"] = "not_non_ptz_context"
            elif self.cubicle_micro_bump_requires_active_memory and not active_event:
                info["ai_cubicle_micro_bump_rejected_reason"] = "missing_active_event_memory"
            elif self.cubicle_micro_bump_requires_not_normal_frame and runtime_normal_frame:
                info["ai_cubicle_micro_bump_rejected_reason"] = "normal_frame"
            elif camera_motion_score > self.cubicle_like_max_camera_motion:
                info["ai_cubicle_micro_bump_rejected_reason"] = "camera_motion_context"
            elif not micro_bump_signal_ok:
                info["ai_cubicle_micro_bump_rejected_reason"] = "micro_signal_low"
            elif self._budget_remaining("cubicle_micro_bump") <= 0:
                info["ai_cubicle_micro_bump_rejected_reason"] = "micro_cap_exhausted"
                info["ai_intervention_budget_blocked"] = 1
            elif cooldown_remaining > 0:
                info["ai_cubicle_micro_bump_rejected_reason"] = "micro_cooldown"
            else:
                cubicle_micro_bump_active = True
                consume_budget("cubicle_micro_bump")
                self.last_cubicle_micro_bump_raw_frame_id = raw_frame_id
                info["ai_cubicle_micro_bump_active"] = 1
                info["ai_cubicle_micro_bump_reason"] = "+".join(dict.fromkeys(micro_reason_parts))
                info["ai_cubicle_micro_bump_no_detector"] = 1
                info["ai_safe_replacement_source"] = "existing_deterministic_no_detector_fallback"
                kinds.append("cubicle_micro_bump_no_detector_fallback")
            info["ai_cubicle_micro_bump_cap_used"] = int(self.budget_counts.get("cubicle_micro_bump", 0))

        exact_cubicle_event_fn_stabilizer_active = False
        if self.exact_cubicle_event_fn_stabilizer_enabled:
            cooldown_remaining = max(
                0,
                self.exact_cubicle_event_fn_stabilizer_cooldown
                - (raw_frame_id - int(self.last_exact_cubicle_event_fn_stabilizer_raw_frame_id)),
            )
            event_model_score_ok = bool(
                max(
                    self._float(ai_info.get("ai_event_foreground_risk_score"), 0.0),
                    self._float(ai_info.get("ai_foreground_loss_risk_score"), 0.0),
                )
                >= self.exact_cubicle_event_fn_stabilizer_event_score_threshold
            )
            foreground_loss_risk_ok = bool(
                max(
                    self._float(ai_info.get("ai_foreground_loss_risk_score"), 0.0),
                    self._float(telemetry.get("foreground_risk"), 0.0),
                )
                >= self.exact_cubicle_event_fn_stabilizer_foreground_loss_threshold
            )
            stabilizer_reason_parts = []
            if current_event_state == "FN" or pre_ai_event_state == "FN":
                stabilizer_reason_parts.append("would_be_unprotected_event_fn")
            if current_known_event or pre_ai_known_event:
                stabilizer_reason_parts.append("known_event_context")
            if active_event:
                stabilizer_reason_parts.append("active_event_memory")
            if recent_event_memory:
                stabilizer_reason_parts.append("recent_event_memory")
            if self._float(telemetry.get("foreground_risk"), 0.0) >= self.exact_cubicle_event_fn_stabilizer_foreground_loss_threshold:
                stabilizer_reason_parts.append("foreground_loss_risk")
            if event_model_score_ok:
                stabilizer_reason_parts.append("event_model_score")
            if foreground_loss_risk_ok:
                stabilizer_reason_parts.append("foreground_loss_score")
            info["ai_exact_cubicle_event_fn_stabilizer_frame"] = str(raw_frame_id)
            info["ai_exact_cubicle_event_fn_stabilizer_would_be_unprotected_fn"] = int(
                current_event_state == "FN" or pre_ai_event_state == "FN"
            )
            if kinds:
                info["ai_exact_cubicle_event_fn_stabilizer_rejected_reason"] = "already_protected"
            elif not exact_cubicle_context:
                info["ai_exact_cubicle_event_fn_stabilizer_rejected_reason"] = "not_exact_shadow_cubicle"
            elif self.exact_cubicle_event_fn_stabilizer_requires_non_ptz and is_ptz:
                info["ai_exact_cubicle_event_fn_stabilizer_rejected_reason"] = "ptz_context"
            elif self.exact_cubicle_event_fn_stabilizer_requires_active_memory and not exact_cubicle_stabilizer_memory_ok:
                info["ai_exact_cubicle_event_fn_stabilizer_rejected_reason"] = "missing_event_memory"
            elif self.exact_cubicle_event_fn_stabilizer_requires_not_normal_frame and not exact_cubicle_stabilizer_not_normal:
                info["ai_exact_cubicle_event_fn_stabilizer_rejected_reason"] = "normal_frame"
            elif camera_motion_score > self.cubicle_like_max_camera_motion:
                info["ai_exact_cubicle_event_fn_stabilizer_rejected_reason"] = "camera_motion_context"
            elif not (event_model_score_ok or foreground_loss_risk_ok):
                info["ai_exact_cubicle_event_fn_stabilizer_rejected_reason"] = "event_foreground_or_loss_score_low"
            elif not exact_cubicle_stabilizer_unprotected_risk:
                info["ai_exact_cubicle_event_fn_stabilizer_rejected_reason"] = "missing_unprotected_fn_risk"
            elif self._budget_remaining("exact_cubicle_event_fn_stabilizer") <= 0:
                info["ai_exact_cubicle_event_fn_stabilizer_rejected_reason"] = "stabilizer_cap_exhausted"
                info["ai_intervention_budget_blocked"] = 1
            elif cooldown_remaining > 0:
                info["ai_exact_cubicle_event_fn_stabilizer_rejected_reason"] = "stabilizer_cooldown"
            else:
                exact_cubicle_event_fn_stabilizer_active = True
                consume_budget("exact_cubicle_event_fn_stabilizer")
                self.last_exact_cubicle_event_fn_stabilizer_raw_frame_id = raw_frame_id
                info["ai_exact_cubicle_event_fn_stabilizer_active"] = 1
                info["ai_exact_cubicle_event_fn_stabilizer_reason"] = "+".join(
                    dict.fromkeys(stabilizer_reason_parts or ["exact_cubicle_event_fn_stability"])
                )
                info["ai_exact_cubicle_event_fn_stabilizer_no_detector"] = 1
                info["ai_exact_cubicle_event_fn_stabilizer_safe_replacement_source"] = (
                    "existing_deterministic_no_detector_fallback"
                )
                info["ai_safe_replacement_source"] = "existing_deterministic_no_detector_fallback"
                kinds.append("exact_cubicle_event_fn_stabilizer_no_detector_fallback")
            info["ai_exact_cubicle_event_fn_stabilizer_cap_used"] = int(
                self.budget_counts.get("exact_cubicle_event_fn_stabilizer", 0)
            )

        exact_cubicle_late_event_rescue_active = False
        if self.exact_cubicle_late_event_rescue_enabled:
            cooldown_remaining = max(
                0,
                self.exact_cubicle_late_event_rescue_cooldown
                - (raw_frame_id - int(self.last_exact_cubicle_late_event_rescue_raw_frame_id)),
            )
            late_reason_parts = []
            if exact_cubicle_context:
                late_reason_parts.append("exact_shadow_cubicle")
            if guard_active:
                late_reason_parts.append("deterministic_guard")
            if exact_cubicle_late_active_memory >= self.exact_cubicle_late_event_rescue_active_memory_min:
                late_reason_parts.append("active_event_memory")
            if exact_cubicle_late_event_score >= self.exact_cubicle_late_event_rescue_event_score_threshold:
                late_reason_parts.append("event_score")
            if (
                exact_cubicle_late_foreground_loss_score
                >= self.exact_cubicle_late_event_rescue_foreground_loss_threshold
            ):
                late_reason_parts.append("foreground_loss_score")
            if current_event_state == "FN" or pre_ai_event_state == "FN":
                late_reason_parts.append("event_fn_risk")
            if exact_cubicle_late_action_ok:
                late_reason_parts.append("unsafe_empty_fallback_action")
            if kinds:
                info["ai_exact_cubicle_late_event_rescue_rejected_reason"] = "already_protected"
            elif not exact_cubicle_context:
                info["ai_exact_cubicle_late_event_rescue_rejected_reason"] = "not_exact_shadow_cubicle"
            elif not guard_active:
                info["ai_exact_cubicle_late_event_rescue_rejected_reason"] = "missing_deterministic_guard"
            elif (
                self.exact_cubicle_late_event_rescue_requires_active_memory
                and exact_cubicle_late_active_memory < self.exact_cubicle_late_event_rescue_active_memory_min
            ):
                info["ai_exact_cubicle_late_event_rescue_rejected_reason"] = "missing_active_event_memory"
            elif not exact_cubicle_late_action_ok:
                info["ai_exact_cubicle_late_event_rescue_rejected_reason"] = "action_not_unsafe_empty_fallback"
            elif not exact_cubicle_late_score_ok:
                info["ai_exact_cubicle_late_event_rescue_rejected_reason"] = "event_or_foreground_loss_score_low"
            elif is_ptz:
                info["ai_exact_cubicle_late_event_rescue_rejected_reason"] = "ptz_context"
            elif exact_cubicle_late_global_motion_active or camera_motion_score > self.cubicle_like_max_camera_motion:
                info["ai_exact_cubicle_late_event_rescue_rejected_reason"] = "ptz_or_global_motion_context"
            elif self._budget_remaining("exact_cubicle_late_event_rescue") <= 0:
                info["ai_exact_cubicle_late_event_rescue_rejected_reason"] = "late_rescue_cap_exhausted"
                info["ai_intervention_budget_blocked"] = 1
            elif cooldown_remaining > 0:
                info["ai_exact_cubicle_late_event_rescue_rejected_reason"] = "late_rescue_cooldown"
            else:
                exact_cubicle_late_event_rescue_active = True
                consume_budget("exact_cubicle_late_event_rescue")
                self.last_exact_cubicle_late_event_rescue_raw_frame_id = raw_frame_id
                info["ai_exact_cubicle_late_event_rescue_active"] = 1
                info["ai_exact_cubicle_late_event_rescue_reason"] = "+".join(
                    dict.fromkeys(late_reason_parts or ["exact_cubicle_late_event_rescue"])
                )
                info["ai_exact_cubicle_late_event_rescue_no_detector"] = 1
                info["ai_safe_replacement_source"] = "existing_deterministic_no_detector_fallback"
                kinds.append("exact_cubicle_late_event_rescue_no_detector_fallback")
            info["ai_exact_cubicle_late_event_rescue_cap_used"] = int(
                self.budget_counts.get("exact_cubicle_late_event_rescue", 0)
            )

        cubicle_live_mismatch_reserve_active = False
        if self.cubicle_live_mismatch_reserve_enabled:
            cooldown_remaining = max(
                0,
                self.cubicle_live_mismatch_reserve_cooldown
                - (raw_frame_id - int(self.last_cubicle_live_mismatch_reserve_raw_frame_id)),
            )
            mismatch_reason_parts = []
            if exact_cubicle_context:
                mismatch_reason_parts.append("exact_shadow_cubicle")
            if cubicle_live_mismatch_action_ok:
                mismatch_reason_parts.append("unsafe_empty_fallback_action")
            if exact_cubicle_late_active_memory >= self.cubicle_live_mismatch_reserve_active_memory_min:
                mismatch_reason_parts.append("active_event_memory")
            if cubicle_live_mismatch_reuse_age >= self.cubicle_live_mismatch_reserve_reuse_age_min:
                mismatch_reason_parts.append("reuse_age")
            if exact_cubicle_late_event_score >= self.cubicle_live_mismatch_reserve_event_score_threshold:
                mismatch_reason_parts.append("event_score")
            if (
                exact_cubicle_late_foreground_loss_score
                >= self.cubicle_live_mismatch_reserve_foreground_loss_threshold
            ):
                mismatch_reason_parts.append("foreground_loss_score")
            if current_event_state == "FN" or pre_ai_event_state == "FN":
                mismatch_reason_parts.append("event_fn_risk")
            if kinds:
                info["ai_cubicle_live_mismatch_reserve_rejected_reason"] = "already_protected"
            elif not exact_cubicle_context:
                info["ai_cubicle_live_mismatch_reserve_rejected_reason"] = "not_exact_shadow_cubicle"
            elif not guard_active:
                info["ai_cubicle_live_mismatch_reserve_rejected_reason"] = "missing_deterministic_guard"
            elif not cubicle_live_mismatch_action_ok:
                info["ai_cubicle_live_mismatch_reserve_rejected_reason"] = "action_not_unsafe_empty_fallback"
            elif exact_cubicle_late_active_memory < self.cubicle_live_mismatch_reserve_active_memory_min:
                info["ai_cubicle_live_mismatch_reserve_rejected_reason"] = "missing_active_event_memory"
            elif cubicle_live_mismatch_reuse_age < self.cubicle_live_mismatch_reserve_reuse_age_min:
                info["ai_cubicle_live_mismatch_reserve_rejected_reason"] = "reuse_age_low"
            elif not cubicle_live_mismatch_score_ok:
                info["ai_cubicle_live_mismatch_reserve_rejected_reason"] = "event_or_foreground_loss_score_low"
            elif runtime_normal_frame:
                info["ai_cubicle_live_mismatch_reserve_rejected_reason"] = "normal_frame"
            elif is_ptz:
                info["ai_cubicle_live_mismatch_reserve_rejected_reason"] = "ptz_context"
            elif exact_cubicle_late_global_motion_active or camera_motion_score > self.cubicle_like_max_camera_motion:
                info["ai_cubicle_live_mismatch_reserve_rejected_reason"] = "ptz_or_global_motion_context"
            elif self._budget_remaining("cubicle_live_mismatch_reserve") <= 0:
                info["ai_cubicle_live_mismatch_reserve_rejected_reason"] = "live_mismatch_reserve_cap_exhausted"
                info["ai_intervention_budget_blocked"] = 1
            elif cooldown_remaining > 0:
                info["ai_cubicle_live_mismatch_reserve_rejected_reason"] = "live_mismatch_reserve_cooldown"
            else:
                cubicle_live_mismatch_reserve_active = True
                consume_budget("cubicle_live_mismatch_reserve")
                self.last_cubicle_live_mismatch_reserve_raw_frame_id = raw_frame_id
                info["ai_cubicle_live_mismatch_reserve_active"] = 1
                info["ai_cubicle_live_mismatch_reserve_reason"] = "+".join(
                    dict.fromkeys(mismatch_reason_parts or ["cubicle_live_mismatch_reserve"])
                )
                info["ai_cubicle_live_mismatch_reserve_no_detector"] = 1
                info["ai_safe_replacement_source"] = "existing_deterministic_no_detector_fallback"
                kinds.append("cubicle_live_mismatch_reserve_no_detector_fallback")
            info["ai_cubicle_live_mismatch_reserve_cap_used"] = int(
                self.budget_counts.get("cubicle_live_mismatch_reserve", 0)
            )

        detector_source = ""
        if (cubicle_like_active and not self.cubicle_like_allow_detector) or (
            cubicle_micro_bump_active and not self.cubicle_micro_bump_allow_detector
        ) or (
            exact_cubicle_event_fn_stabilizer_active and not self.exact_cubicle_event_fn_stabilizer_allow_detector
        ) or (
            exact_cubicle_late_event_rescue_active and not self.exact_cubicle_late_event_rescue_allow_detector
        ) or (
            cubicle_live_mismatch_reserve_active and not self.cubicle_live_mismatch_reserve_allow_detector
        ) or (
            ptz_live_mismatch_rescue_pre_signal
            and not self.ptz_intermittent_pan_live_mismatch_rescue_allow_detector
        ) or (
            copymachine_rescue_pre_signal and not self.copymachine_fn_rescue_allow_detector
        ) or (
            copymachine_rescue_first_pre_signal and not self.copymachine_rescue_first_allow_detector
        ) or (
            copymachine_live_cap_reserve_pre_signal
            and not self.copymachine_live_cap_reserve_allow_detector
        ) or (
            parking_iom_rescue_pre_signal and not self.parking_iom_rescue_allow_detector
        ) or (
            sofa_iom_rescue_pre_signal and not self.sofa_iom_rescue_allow_detector
        ) or (
            snowfall_weather_rescue_pre_signal
            and not self.snowfall_weather_rescue_allow_detector
        ) or (
            snowfall_actual_fn_rescue_pre_signal
            and not self.snowfall_actual_fn_rescue_allow_detector
        ) or (
            parking_live_cap_reserve_pre_signal
            and not self.parking_live_cap_reserve_allow_detector
        ) or (
            parking_live_burst_bridge_pre_signal
            and not self.parking_live_burst_bridge_allow_detector
        ) or (
            tunnel_exit_lf_rescue_pre_signal and not self.tunnel_exit_lf_rescue_allow_detector
        ):
            if detector_refresh or detector or event_foreground:
                detector_blocked_for_refresh = True
                info["ai_detector_request_rejected_event_foreground_only"] = int(event_foreground or detector)
        elif detector_refresh:
            detector_source = "detector_refresh_needed_for_event"
            info["ai_detector_request_event_refresh_specific"] = 1
        elif detector and event_any and strong_event_context and not self.event_foreground_detector_requires_refresh_model:
            detector_source = "detector_needed_under_event_foreground_risk"
        elif event_foreground and self.event_foreground_allow_detector_direct and strong_event_context and not self.event_foreground_detector_requires_refresh_model:
            detector_source = "event_foreground_direct"
        elif detector or event_foreground:
            detector_blocked_for_refresh = True
            info["ai_detector_request_blocked_no_refresh_model"] = int(
                self.intervention_detector_requires_refresh_model or self.event_foreground_detector_requires_refresh_model
            )
            if event_foreground or event_fg_block_only_active:
                info["ai_detector_request_rejected_event_foreground_only"] = 1

        if (
            (self.intervention_detector_requires_refresh_model or self.event_foreground_detector_requires_refresh_model)
            and detector_source in {"event_foreground_direct", "detector_needed_under_event_foreground_risk"}
        ):
            detector_source = ""
            detector_blocked_for_refresh = True
            info["ai_detector_request_blocked_no_refresh_model"] = 1
            info["ai_detector_request_rejected_event_foreground_only"] = 1

        if detector_source and self.intervention_allow_detector:
            min_gap = int(self.intervention_budget.get("min_detector_interval_frames", 1))
            frames_since_detector = self._float(telemetry.get("frames_since_last_detector"), 10**9)
            interval_remaining = max(
                0,
                min_gap - min(
                    int(frames_since_detector),
                    evaluated_index - int(self.last_ai_detector_eval_index),
                ),
            )
            info["ai_detector_interval_remaining"] = int(interval_remaining)
            if interval_remaining > 0:
                info["ai_intervention_cadence_blocked"] = 1
                info["ai_detector_request_blocked_interval"] = 1
            elif (
                self.bridge_entry_detector_budget_max >= 0
                and video_name == "bridgeEntry"
                and int(self.budget_counts.get("detector", 0)) >= self.bridge_entry_detector_budget_max
            ):
                info["ai_intervention_budget_blocked"] = 1
                info["ai_detector_request_blocked_budget"] = 1
            elif self._budget_remaining("detector") > 0:
                consume_budget("detector")
                self.last_ai_detector_eval_index = evaluated_index
                info["ai_intervention_detector_requested"] = 1
                info["ai_detector_request_source"] = detector_source
                if kinds:
                    info["ai_detector_last_resort_used"] = 1
                kinds.append("request_detector")
            else:
                info["ai_intervention_budget_blocked"] = 1
                info["ai_detector_request_blocked_budget"] = 1
        elif detector_blocked_for_refresh and not kinds:
            info["ai_detector_request_blocked_no_refresh_model"] = 1

        target_video_key = f"{telemetry.get('category', '')}/{video_name}".replace("\\", "/")
        turbulence2_rescue_active = False
        turbulence2_carryover_reserve_active = False
        thermal_lakeside_fn_rescue_active = False
        thermal_lakeside_early_memory_rescue_active = False
        tunnel_exit_lf_rescue_active = False
        tunnel_exit_lf_preserve_fn_risk_active = False
        snowfall_weather_rescue_active = False
        snowfall_actual_fn_rescue_active = False
        ptz_live_mismatch_rescue_active = False
        copymachine_live_cap_reserve_active = False
        parking_carryover_lock_active = False
        sofa_iom_carryover_lock_active = False
        parking_live_cap_reserve_active = False
        parking_live_burst_bridge_active = False

        def clear_current_proposal():
            nonlocal kinds
            nonlocal event_fg_block_only_active
            nonlocal cubicle_like_active
            nonlocal cubicle_micro_bump_active
            nonlocal exact_cubicle_event_fn_stabilizer_active
            nonlocal exact_cubicle_late_event_rescue_active
            nonlocal cubicle_live_mismatch_reserve_active
            nonlocal ptz_rescue_active
            nonlocal ptz_live_mismatch_rescue_active
            nonlocal copymachine_rescue_active
            nonlocal copymachine_live_cap_reserve_active
            nonlocal parking_iom_rescue_active
            nonlocal parking_carryover_lock_active
            nonlocal parking_iom_preserve_fn_risk_active
            nonlocal sofa_iom_carryover_lock_active
            nonlocal parking_live_cap_reserve_active
            nonlocal parking_live_burst_bridge_active
            nonlocal turbulence2_rescue_active
            nonlocal turbulence2_carryover_reserve_active
            nonlocal thermal_lakeside_fn_rescue_active
            nonlocal thermal_lakeside_early_memory_rescue_active
            nonlocal tunnel_exit_lf_rescue_active
            nonlocal tunnel_exit_lf_preserve_fn_risk_active

            refund_frame_budgets()
            self.last_ai_detector_eval_index = previous_last_ai_detector_eval_index
            self.last_cubicle_like_raw_frame_id = previous_last_cubicle_like_raw_frame_id
            self.last_cubicle_micro_bump_raw_frame_id = previous_last_cubicle_micro_bump_raw_frame_id
            self.last_exact_cubicle_event_fn_stabilizer_raw_frame_id = (
                previous_last_exact_cubicle_event_fn_stabilizer_raw_frame_id
            )
            self.last_exact_cubicle_late_event_rescue_raw_frame_id = (
                previous_last_exact_cubicle_late_event_rescue_raw_frame_id
            )
            self.last_cubicle_live_mismatch_reserve_raw_frame_id = (
                previous_last_cubicle_live_mismatch_reserve_raw_frame_id
            )
            self.last_ptz_intermittent_pan_fn_rescue_raw_frame_id = (
                previous_last_ptz_intermittent_pan_fn_rescue_raw_frame_id
            )
            self.last_ptz_intermittent_pan_live_mismatch_rescue_raw_frame_id = (
                previous_last_ptz_intermittent_pan_live_mismatch_rescue_raw_frame_id
            )
            self.last_copymachine_fn_rescue_raw_frame_id = previous_last_copymachine_fn_rescue_raw_frame_id
            self.last_copymachine_live_cap_reserve_raw_frame_id = (
                previous_last_copymachine_live_cap_reserve_raw_frame_id
            )
            self.last_parking_iom_rescue_raw_frame_id = previous_last_parking_iom_rescue_raw_frame_id
            self.last_parking_live_cap_reserve_raw_frame_id = (
                previous_last_parking_live_cap_reserve_raw_frame_id
            )
            self.last_parking_live_burst_bridge_raw_frame_id = (
                previous_last_parking_live_burst_bridge_raw_frame_id
            )
            self.last_parking_live_preserve_or_rescue_raw_frame_id = (
                previous_last_parking_live_preserve_or_rescue_raw_frame_id
            )
            self.last_turbulence2_fn_rescue_raw_frame_id = (
                previous_last_turbulence2_fn_rescue_raw_frame_id
            )
            self.last_turbulence2_carryover_reserve_raw_frame_id = (
                previous_last_turbulence2_carryover_reserve_raw_frame_id
            )
            self.last_thermal_lakeside_fn_rescue_raw_frame_id = (
                previous_last_thermal_lakeside_fn_rescue_raw_frame_id
            )
            self.last_thermal_lakeside_early_memory_rescue_raw_frame_id = (
                previous_last_thermal_lakeside_early_memory_rescue_raw_frame_id
            )
            self.last_tunnel_exit_lf_rescue_raw_frame_id = (
                previous_last_tunnel_exit_lf_rescue_raw_frame_id
            )
            kinds = []
            event_fg_block_only_active = False
            cubicle_like_active = False
            cubicle_micro_bump_active = False
            exact_cubicle_event_fn_stabilizer_active = False
            exact_cubicle_late_event_rescue_active = False
            cubicle_live_mismatch_reserve_active = False
            ptz_rescue_active = False
            ptz_live_mismatch_rescue_active = False
            copymachine_rescue_active = False
