            thermal_lakeside_fn_rescue_active = False
            thermal_lakeside_early_memory_rescue_active = False
            tunnel_exit_lf_rescue_active = False
            tunnel_exit_lf_preserve_fn_risk_active = False
            info["ai_intervention_detector_requested"] = 0
            info["ai_intervention_closed_empty_blocked"] = 0
