def normalized(series):
    min_v = float(series.min())
    max_v = float(series.max())
    if max_v <= min_v:
        return pd.Series([1.0] * len(series), index=series.index)
    return (series - min_v) / (max_v - min_v)

def add_research_score(df):
    if df.empty:
        return df
    out = df.copy()
    fps_col = "Avg_FPS" if "Avg_FPS" in out.columns else "avg_FPS"
    activation_col = "Activation" if "Activation" in out.columns else "YOLO_activation_rate"
    out["normalized_Avg_FPS"] = normalized(out[fps_col].astype(float))
    out["Research_Score"] = (
        0.4 * out["FMeasure"].astype(float)
        + 0.3 * out["Event_F1"].astype(float)
        + 0.2 * (1.0 - out[activation_col].astype(float))
        + 0.1 * out["normalized_Avg_FPS"].astype(float)
    )
    return out

def build_pipeline_comparison(research_summary, pipelines=None):
    if research_summary.empty:
        return pd.DataFrame()
    df = research_summary.copy()
    if pipelines:
        df = df[df["pipeline"].isin(pipelines)]
    grouped = df.groupby("pipeline", as_index=False).agg(
        FMeasure=("FMeasure", "mean"),
        Event_F1=("Event_F1", "mean"),
        Activation=("YOLO_activation_rate", "mean"),
        Avg_FPS=("avg_FPS", "mean"),
        P95_latency=("P95_latency_ms", "mean"),
        Reuse_rate=("reused_prediction_rate", "mean"),
        reused_prediction_count=("reused_prediction_count", "sum"),
    )
    grouped = grouped.rename(columns={"pipeline": "Pipeline"})
    return add_research_score(grouped)

def build_asmag_ablation_table(research_summary):
    desired = [
        ("P4_ASMAG_PLUS", "P4_ASMAG_PLUS"),
        ("P4_PRECISION", "P4_PRECISION"),
        ("P4_BALANCED", "P4_BALANCED"),
        ("P4_EFFICIENT", "P4_EFFICIENT"),
        ("P4_EFFICIENT_REUSE", "P4_EFFICIENT_REUSE"),
        ("ASMAG_TR_ACC", "ASMAG_TR_ACC"),
        ("ASMAG_TR_FAST", "ASMAG_TR_FAST"),
    ]
    comparison = build_pipeline_comparison(research_summary)
    rows = []
    for label, pipeline in desired:
        found = comparison[comparison["Pipeline"] == pipeline]
        if found.empty:
            row = {
                "Pipeline": label,
                "FMeasure": None,
                "Event_F1": None,
                "Activation": None,
                "Avg_FPS": None,
                "P95_latency": None,
                "Reuse_rate": None,
                "reused_prediction_count": None,
                "normalized_Avg_FPS": None,
                "Research_Score": None,
                "status": "not_run_in_this_experiment",
            }
        else:
            row = found.iloc[0].to_dict()
            row["Pipeline"] = label
            row["status"] = "ok"
        rows.append(row)
    return pd.DataFrame(rows)

def cpu_ram_percent(proc, simulated_cores=2, simulated_ram_gb=4):
    cpu = proc.cpu_percent(interval=None) / max(1, simulated_cores)
    ram = (proc.memory_info().rss / (1024*1024)) / (simulated_ram_gb*1024) * 100
    return cpu, ram

def draw_qualitative(frame, gt, pred_mask, out_path):
    if gt.ndim == 3:
        gt = gt[:, :, 0]
    vis = frame.copy()
    overlay = vis.copy()
    overlay[pred_mask > 0] = (0, 255, 255)
    overlay[gt == 255] = (0, 255, 0)
    vis = cv2.addWeighted(vis, 0.65, overlay, 0.35, 0)
    cv2.imwrite(str(out_path), vis)

def mask_area(mask):
    return int(np.sum(mask > 0)) if mask is not None else 0

def mask_iou(a, b):
    if a is None or b is None:
        return 0.0
    aa = a > 0
    bb = b > 0
    union = int(np.logical_or(aa, bb).sum())
    if union <= 0:
        return 1.0
    return float(np.logical_and(aa, bb).sum()) / float(union)

def coarse_grid_occupancy(mask, grid=8):
    if mask is None:
        return 0.0
    binary = mask > 0
    if not np.any(binary):
        return 0.0
    h, w = binary.shape[:2]
    occupied = 0
    total = grid * grid
    for gy in range(grid):
        y0 = int(round(gy * h / float(grid)))
        y1 = int(round((gy + 1) * h / float(grid)))
        for gx in range(grid):
            x0 = int(round(gx * w / float(grid)))
            x1 = int(round((gx + 1) * w / float(grid)))
            if np.any(binary[y0:y1, x0:x1]):
                occupied += 1
    return occupied / float(max(1, total))

def edge_touch_ratio(mask, border_fraction=0.05):
    if mask is None:
        return 0.0
    binary = mask > 0
    area = int(binary.sum())
    if area <= 0:
        return 0.0
    h, w = binary.shape[:2]
    by = max(1, int(round(h * border_fraction)))
    bx = max(1, int(round(w * border_fraction)))
    edge = np.zeros(binary.shape, dtype=bool)
    edge[:by, :] = True
    edge[-by:, :] = True
    edge[:, :bx] = True
    edge[:, -bx:] = True
    return float(np.logical_and(binary, edge).sum()) / float(area)

def component_count_and_largest_ratio(mask):
    if mask is None:
        return 0, 0.0
    binary = (mask > 0).astype(np.uint8)
    if int(binary.sum()) <= 0:
        return 0, 0.0
    num, _, stats, _ = cv2.connectedComponentsWithStats(binary, 8)
    if num <= 1:
        return 0, 0.0
    areas = stats[1:, cv2.CC_STAT_AREA]
    total = float(max(1, int(areas.sum())))
    return int(num - 1), float(np.max(areas)) / total

def candidate_pairwise_disagreement(masks):
    valid = [m for m in masks if m is not None]
    if len(valid) < 2:
        return 0.0
    ious = []
    for i in range(len(valid)):
        for j in range(i + 1, len(valid)):
            ious.append(mask_iou(valid[i], valid[j]))
    if not ious:
        return 0.0
    return 1.0 - float(np.mean(ious))

def candidate_mask_quality(mask, image_area, previous_mask=None, peer_disagreement=0.0, global_motion_risk=0.0, whole_frame_threshold=0.35):
    area = mask_area(mask)
    area_ratio = area / float(max(1, image_area))
    metric_mask = mask
    metric_previous = previous_mask
    if mask is not None and mask.shape[1] > 160:
        scale = 160.0 / float(mask.shape[1])
        metric_size = (160, max(1, int(round(mask.shape[0] * scale))))
        metric_mask = cv2.resize(mask, metric_size, interpolation=cv2.INTER_NEAREST)
        if previous_mask is not None and previous_mask.shape[:2] == mask.shape[:2]:
            metric_previous = cv2.resize(previous_mask, metric_size, interpolation=cv2.INTER_NEAREST)
    component_count, largest_component_ratio = component_count_and_largest_ratio(metric_mask)
    grid_occupancy = coarse_grid_occupancy(metric_mask)
    edge_ratio = edge_touch_ratio(metric_mask)
    temporal_iou = mask_iou(metric_mask, metric_previous) if metric_previous is not None else 0.5

    if area <= 0:
        area_score = 0.0
    elif global_motion_risk >= 0.65:
        area_score = 1.0 - normalize01(max(0.0, area_ratio - whole_frame_threshold), max(1e-6, 1.0 - whole_frame_threshold))
        area_score *= min(1.0, area_ratio / 0.02)
    else:
        area_score = min(1.0, area_ratio / 0.02)

    if component_count <= 0:
        component_score = 0.0
    elif component_count <= 20:
        component_score = 0.65 + 0.35 * largest_component_ratio
    else:
        component_score = max(0.0, 1.0 - normalize01(component_count - 20, 80.0))
        component_score = max(component_score, 0.25 * largest_component_ratio)

    spread_penalty = grid_occupancy if global_motion_risk >= 0.65 else max(0.0, grid_occupancy - 0.85)
    spread_score = max(0.0, 1.0 - spread_penalty)
    edge_score = max(0.0, 1.0 - edge_ratio)
    agreement_score = max(0.0, 1.0 - peer_disagreement)
    temporal_score = max(0.0, min(1.0, temporal_iou))
    density_consistency = 0.5
    if previous_mask is not None:
        prev_area_ratio = mask_area(previous_mask) / float(max(1, image_area))
        density_consistency = max(0.0, 1.0 - normalize01(abs(area_ratio - prev_area_ratio), 0.15))

    whole_frame_penalty = 0.0
    if global_motion_risk >= 0.65:
        whole_frame_penalty = normalize01(max(0.0, area_ratio - whole_frame_threshold), max(1e-6, 1.0 - whole_frame_threshold))

    quality = (
        0.20 * area_score
        + 0.18 * component_score
        + 0.15 * spread_score
        + 0.12 * edge_score
        + 0.15 * temporal_score
        + 0.15 * agreement_score
        + 0.05 * density_consistency
        - 0.20 * whole_frame_penalty
    )
    quality = max(0.0, min(1.0, quality))
    return {
        "area_ratio": area_ratio,
        "component_count": component_count,
        "largest_component_ratio": largest_component_ratio,
        "coarse_grid_occupancy": grid_occupancy,
        "edge_touch_ratio": edge_ratio,
        "temporal_iou": temporal_iou,
        "quality": quality,
    }

def resize_gray_for_motion(frame, resize_width=160):
    if frame is None:
        return None, 1.0, 1.0
    gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY) if frame.ndim == 3 else frame.copy()
    h, w = gray.shape[:2]
    if resize_width and w > resize_width:
        scale = float(resize_width) / float(w)
        size = (int(resize_width), max(1, int(round(h * scale))))
        gray_small = cv2.resize(gray, size, interpolation=cv2.INTER_AREA)
        return gray_small, float(w) / float(size[0]), float(h) / float(size[1])
    return gray, 1.0, 1.0

def warp_translation(image, dx, dy, interpolation=cv2.INTER_NEAREST):
    if image is None:
        return None
    matrix = np.float32([[1.0, 0.0, float(dx)], [0.0, 1.0, float(dy)]])
    return cv2.warpAffine(
        image,
        matrix,
        (image.shape[1], image.shape[0]),
        flags=interpolation,
        borderMode=cv2.BORDER_CONSTANT,
        borderValue=0,
    )

def estimate_phase_correlation_probe(prev_frame, frame, previous_mask=None, candidate_masks=None, resize_width=160):
    result = {
        "active": 0,
        "compute_ms": 0.0,
        "dx": 0.0,
        "dy": 0.0,
        "shift_mag": 0.0,
        "response": 0.0,
        "residual_ratio": 1.0,
        "residual_reason": "",
        "failure_reason": "",
        "warped_previous_mask": None,
        "temporal_iou": {"P3_FALLBACK": 0.0, "ACC": 0.0, "FAST": 0.0},
    }
    if prev_frame is None or frame is None:
        result["failure_reason"] = "missing_previous_frame"
        return result
    t0 = time.time()
    try:
        prev_small, sx, sy = resize_gray_for_motion(prev_frame, resize_width)
        cur_small, _, _ = resize_gray_for_motion(frame, resize_width)
        if prev_small is None or cur_small is None or prev_small.shape != cur_small.shape:
            result["failure_reason"] = "shape_mismatch"
            return result
        prev_float = cv2.GaussianBlur(prev_small, (5, 5), 0).astype(np.float32)
        cur_float = cv2.GaussianBlur(cur_small, (5, 5), 0).astype(np.float32)
        window = cv2.createHanningWindow((prev_float.shape[1], prev_float.shape[0]), cv2.CV_32F)
        (dx_small, dy_small), response = cv2.phaseCorrelate(prev_float, cur_float, window)
        # Try both signs and keep the alignment with lower residual; OpenCV shift
        # sign can be unintuitive across preprocessing variants.
        residual_candidates = []
        for sign in (1.0, -1.0):
            shifted = warp_translation(prev_small, sign * dx_small, sign * dy_small, interpolation=cv2.INTER_LINEAR)
            if shifted is None:
                continue
            diff = cv2.absdiff(shifted, cur_small)
            residual_candidates.append((float(np.mean(diff > 25)), sign))
        if residual_candidates:
            residual_ratio, sign = min(residual_candidates, key=lambda item: item[0])
        else:
            residual_ratio, sign = 1.0, 1.0
        dx = sign * float(dx_small) * sx
        dy = sign * float(dy_small) * sy
        result.update({
            "active": 1,
            "dx": dx,
            "dy": dy,
            "shift_mag": math.hypot(dx, dy),
            "response": float(response),
            "residual_ratio": float(residual_ratio),
            "residual_reason": "aligned" if residual_ratio <= 0.35 else "high_residual_after_shift",
            "failure_reason": "",
        })
        if previous_mask is not None:
            warped_mask = warp_translation(previous_mask, dx, dy, interpolation=cv2.INTER_NEAREST)
            result["warped_previous_mask"] = warped_mask
            for mode_name, mode_mask in (candidate_masks or {}).items():
                result["temporal_iou"][mode_name] = mask_iou(warped_mask, mode_mask)
    except Exception as exc:
        result["failure_reason"] = f"phase_correlation_error:{type(exc).__name__}"
    finally:
        result["compute_ms"] = (time.time() - t0) * 1000.0
    return result

def estimate_orb_affine_geometry_probe(
    prev_frame,
    frame,
    previous_mask=None,
    candidate_masks=None,
    resize_width=240,
    max_features=200,
    min_matches=12,
    min_inlier_ratio=0.25,
    max_compute_ms=20.0,
):
    result = {
        "active": 0,
        "success": 0,
        "compute_ms": 0.0,
        "failure_reason": "",
        "matches": 0,
        "inliers": 0,
        "inlier_ratio": 0.0,
        "dx": 0.0,
        "dy": 0.0,
        "shift_mag": 0.0,
        "scale": 1.0,
        "rotation_deg": 0.0,
        "model_type": "orb_affine_partial",
        "residual_ratio": 1.0,
        "warped_previous_mask": None,
        "temporal_iou": {"P3_FALLBACK": 0.0, "ACC": 0.0, "FAST": 0.0},
    }
    if prev_frame is None or frame is None:
        result["failure_reason"] = "missing_previous_frame"
        return result
    t0 = time.time()
    try:
        prev_small, sx, sy = resize_gray_for_motion(prev_frame, resize_width)
        cur_small, _, _ = resize_gray_for_motion(frame, resize_width)
        if prev_small is None or cur_small is None or prev_small.shape != cur_small.shape:
            result["failure_reason"] = "shape_mismatch"
            return result
        result["active"] = 1
        orb = cv2.ORB_create(nfeatures=max(20, int(max_features)), fastThreshold=12)
        kp_prev, desc_prev = orb.detectAndCompute(prev_small, None)
        kp_cur, desc_cur = orb.detectAndCompute(cur_small, None)
        if desc_prev is None or desc_cur is None or len(kp_prev) < 4 or len(kp_cur) < 4:
            result["failure_reason"] = "insufficient_features"
            return result
        matcher = cv2.BFMatcher(cv2.NORM_HAMMING, crossCheck=True)
        matches = matcher.match(desc_prev, desc_cur)
        matches = sorted(matches, key=lambda m: m.distance)[: max(int(max_features), int(min_matches))]
        result["matches"] = int(len(matches))
        if len(matches) < int(min_matches):
            result["failure_reason"] = "insufficient_matches"
            return result
        src_pts = np.float32([kp_prev[m.queryIdx].pt for m in matches]).reshape(-1, 1, 2)
        dst_pts = np.float32([kp_cur[m.trainIdx].pt for m in matches]).reshape(-1, 1, 2)
        matrix_small, inlier_mask = cv2.estimateAffinePartial2D(
            src_pts,
            dst_pts,
            method=cv2.RANSAC,
            ransacReprojThreshold=3.0,
            maxIters=500,
            confidence=0.98,
            refineIters=5,
        )
        if matrix_small is None or inlier_mask is None:
            result["failure_reason"] = "affine_estimate_failed"
            return result
        inliers = int(np.sum(inlier_mask > 0))
        inlier_ratio = inliers / float(max(1, len(matches)))
        result["inliers"] = inliers
        result["inlier_ratio"] = float(inlier_ratio)
        if inliers < int(min_matches) or inlier_ratio < float(min_inlier_ratio):
            result["failure_reason"] = "low_inlier_ratio"
            return result
        elapsed_ms = (time.time() - t0) * 1000.0
        if elapsed_ms > float(max_compute_ms):
            result["failure_reason"] = "compute_budget_exceeded"
            return result
        a = float(matrix_small[0, 0])
        b = float(matrix_small[0, 1])
        c = float(matrix_small[1, 0])
        scale = math.sqrt(max(0.0, a * a + c * c))
        rotation_deg = math.degrees(math.atan2(c, a))
        full_matrix = matrix_small.astype(np.float32).copy()
        full_matrix[0, 2] *= float(sx)
        full_matrix[1, 2] *= float(sy)
        dx = float(full_matrix[0, 2])
        dy = float(full_matrix[1, 2])
        warped_small = cv2.warpAffine(
            prev_small,
            matrix_small.astype(np.float32),
            (cur_small.shape[1], cur_small.shape[0]),
            flags=cv2.INTER_LINEAR,
            borderMode=cv2.BORDER_CONSTANT,
            borderValue=0,
        )
        residual_ratio = float(np.mean(cv2.absdiff(warped_small, cur_small) > 25))
        result.update({
            "success": 1,
            "failure_reason": "",
            "dx": dx,
            "dy": dy,
            "shift_mag": math.hypot(dx, dy),
            "scale": float(scale),
            "rotation_deg": float(rotation_deg),
            "residual_ratio": residual_ratio,
        })
        if previous_mask is not None:
            warped_mask = cv2.warpAffine(
                previous_mask,
                full_matrix,
                (previous_mask.shape[1], previous_mask.shape[0]),
                flags=cv2.INTER_NEAREST,
                borderMode=cv2.BORDER_CONSTANT,
                borderValue=0,
            )
            result["warped_previous_mask"] = warped_mask
            for mode_name, mode_mask in (candidate_masks or {}).items():
                result["temporal_iou"][mode_name] = mask_iou(warped_mask, mode_mask)
    except Exception as exc:
        result["failure_reason"] = f"orb_affine_error:{type(exc).__name__}"
    finally:
        result["compute_ms"] = (time.time() - t0) * 1000.0
    return result

def mask_panel(mask, title):
    if mask.ndim == 3:
        mask = mask[:, :, 0]
    panel = np.zeros((mask.shape[0], mask.shape[1], 3), dtype=np.uint8)
    panel[mask > 0] = (255, 255, 255)
    return label_panel(panel, title)

def gt_panel(gt, title="GT"):
    if gt.ndim == 3:
        gt = gt[:, :, 0]
    panel = np.zeros((gt.shape[0], gt.shape[1], 3), dtype=np.uint8)
    panel[gt == 0] = (20, 20, 20)
    panel[(gt == 50) | (gt == 85)] = (120, 120, 120)
    panel[gt == 170] = (0, 180, 180)
    panel[gt == 255] = (0, 220, 0)
    return label_panel(panel, title)

def label_panel(img, title):
    out = img.copy()
    cv2.rectangle(out, (0, 0), (out.shape[1], 24), (0, 0, 0), -1)
    cv2.putText(out, title, (6, 17), cv2.FONT_HERSHEY_SIMPLEX, 0.48, (255, 255, 255), 1, cv2.LINE_AA)
    return out

def write_p4_diagnostics(out_root, diagnostics, always_frames=None, top_n=10):
    if not diagnostics:
        return
    always_frames = set(always_frames or [])
    selected = set(always_frames)
    selected.update(d["frame_id"] for d in sorted(diagnostics, key=lambda x: x["FP_pixel"], reverse=True)[:top_n])
    diag_dir = ensure(Path(out_root) / "p4_diagnostics")
    rows = []

    for d in diagnostics:
        if d["frame_id"] not in selected:
            continue
        frame_dir = ensure(diag_dir / f"frame_{d['frame_id']:06d}")
        masks = d["masks"]
        for name in [
            "fd_mask",
            "mog_mask",
            "knn_mask",
            "gate_mask_before_filter",
            "filter_mask_after_component",
            "final_pred_mask",
        ]:
            cv2.imwrite(str(frame_dir / f"{name}.png"), masks[name])

        if d["frame_id"] in always_frames:
            panels = [
                label_panel(d["frame"], f"original {d['frame_id']:06d}"),
                gt_panel(d["gt"], "GT"),
                mask_panel(masks["fd_mask"], "fd_mask"),
                mask_panel(masks["mog_mask"], "mog_mask"),
                mask_panel(masks["knn_mask"], "knn_mask"),
                mask_panel(masks["gate_mask_before_filter"], "gate_mask"),
                mask_panel(masks["filter_mask_after_component"], "filter_mask"),
                mask_panel(masks["final_pred_mask"], "final_pred_mask"),
            ]
            cv2.imwrite(str(diag_dir / f"grid_{d['frame_id']:06d}.png"), np.hstack(panels))

        row = {k: d[k] for k in [
            "frame_id",
            "fd_area",
            "mog_area",
            "knn_area",
            "gate_area",
            "filter_area",
            "final_area",
            "gt_area",
            "FP_pixel",
            "FN_pixel",
            "FMeasure",
            "gate_score",
            "component_entropy_mean",
            "kept_components",
            "watchdog_triggered",
        ]}
        rows.append(row)

    pd.DataFrame(rows).sort_values(["FP_pixel", "frame_id"], ascending=[False, True]).to_csv(
        diag_dir / "p4_mask_source_diagnostics.csv", index=False
    )

def process_sequence(cfg, seq, pipeline_name, detector, frames_source=None, gts_source=None, progress_path=None, session_started_at=None):
    controller_selected_mode = controller_mode_for_category(seq["category"]) if pipeline_name == "ASMAG_TR_CONTROLLER" else ""
    category_policy_mode = controller_selected_mode
    execution_pipeline_name = effective_pipeline_name(pipeline_name, seq["category"])
    pipeline_key = canonical_pipeline_name(execution_pipeline_name)
    is_guarded_online_controller = pipeline_name == ONLINE_CONTROLLER_GUARDED_PIPELINE
    is_online_controller = pipeline_name in ONLINE_CONTROLLER_PIPELINES
    exp = cfg["experiment_name"]
    out_root = Path(cfg.get("output_root", "outputs")) / exp
    seq_out = ensure(out_root / "raw_results" / seq["category"] / seq["video"] / pipeline_name)
    mask_dir = ensure(seq_out / "masks")
    resume_paths = {
        "event": seq_out / "sequence_event_summary.csv",
        "pixel": seq_out / "sequence_pixel_summary.csv",
        "edge": seq_out / "sequence_edge_summary.csv",
        "object": seq_out / "sequence_object_summary.csv",
    }
    expected_for_resume = expected_eval_frame_count(seq, cfg)
    if bool(cfg.get("resume_existing_results", False)) and sequence_result_complete(
        out_root,
        seq["category"],
        seq["video"],
        pipeline_name,
        expected_for_resume,
    ):
        return tuple(pd.read_csv(path).iloc[0].to_dict() for path in resume_paths.values())

    eval_cfg = cfg.get("evaluation", {})
    cdnet_gt_config = cfg.get("cdnet_gt", {})
    energy_cfg = cfg.get("energy_proxy", {})
    frame_step = int(eval_cfg.get("frame_step", 1))
    max_frames = eval_cfg.get("max_frames_per_video", None)
    save_masks = bool(eval_cfg.get("save_binary_masks", True))
    save_qual = bool(eval_cfg.get("save_qualitative_samples", False))
    use_temporal_roi = bool(eval_cfg.get("use_temporal_roi", False))
    warmup_frames = int(eval_cfg.get("warmup_frames", eval_cfg.get("warmup_frames_before_roi", 0)))
    temporal_roi_start, temporal_roi_end = None, None
    skipped_frames_before_roi = 0

    if frames_source is None:
        frame_files, gt_files = list_frames(seq["input_dir"], seq["gt_dir"])
        gt_by_number = {frame_number(p): p for p in gt_files if frame_number(p) is not None}
        roi_start, roi_end = seq.get("roi_start"), seq.get("roi_end")
        temporal_roi_start, temporal_roi_end = roi_start, roi_end
        eval_positions = []
        if use_temporal_roi and roi_start is not None and roi_end is not None:
            eval_positions = [
                i for i, p in enumerate(frame_files)
                if frame_number(p) is not None and roi_start <= frame_number(p) <= roi_end
            ]
            skipped_frames_before_roi = eval_positions[0] if eval_positions else 0
        else:
            eval_positions = list(range(len(frame_files)))
    else:
        frame_files, gt_files = frames_source, gts_source
        gt_by_number = {}
        eval_positions = list(range(len(frames_source)))

    if max_frames:
        eval_positions = eval_positions[:int(max_frames)]
    eval_positions = eval_positions[::frame_step]
    eval_position_set = set(eval_positions)
    uses_bg_subtractor = pipeline_key in {
        "P3_MOG2",
        "P4_ASMAG_PLUS",
        "P4_ASMAG_PLUS_PRECISION",
        "P4_ASMAG_PLUS_BALANCED",
        "P4_ASMAG_PLUS_EFFICIENT",
        "P4_ASMAG_PLUS_EFFICIENT_REUSE",
    } or is_online_controller
    if eval_positions and frames_source is None and uses_bg_subtractor:
        loop_positions = range(eval_positions[0], eval_positions[-1] + 1)
    else:
        loop_positions = eval_positions
    if eval_positions and frames_source is None and uses_bg_subtractor and warmup_frames > 0:
        warmup_start = max(0, eval_positions[0] - warmup_frames)
        warmup_positions = range(warmup_start, eval_positions[0])
    else:
        warmup_positions = []
    total_eval_frames = len(eval_positions)

    online_gates = {}
    guarded_gate_bank = None
    ai_shadow_policy = None
    online_estimator = None
    if is_guarded_online_controller:
        guarded_gate_bank = SharedGuardedGateBank(cfg)
        ai_shadow_policy = AIShadowPolicy(cfg.get("online_controller_guarded", {}))
        online_cfg_key = "online_controller_guarded"
        online_estimator = OnlineSceneDifficultyEstimator(cfg.get(online_cfg_key, cfg.get("online_controller_calibrated", {})))
        gate = None
    elif is_online_controller:
        online_gates = {
            "P3_FALLBACK": MOG2Gate(min_area_ratio=cfg.get("p4_asmag_plus", {}).get("min_area_ratio", 0.001)),
            "ACC": ASMAGPlusEfficientGate(p4_efficient_cfg_for_pipeline(cfg, "ASMAG_TR_ACC")),
            "FAST": ASMAGPlusEfficientGate(p4_efficient_cfg_for_pipeline(cfg, "ASMAG_TR_FAST")),
        }
        if pipeline_name in {ONLINE_CONTROLLER_CALIBRATED_PIPELINE, ONLINE_CALIBRATED_ALIAS_PIPELINE}:
            online_cfg_key = "online_controller_calibrated"
        elif pipeline_name == ONLINE_CONTROLLER_P3TUNED_PIPELINE:
            online_cfg_key = "online_controller_p3tuned"
        else:
            online_cfg_key = "online_controller"
        online_estimator = OnlineSceneDifficultyEstimator(cfg.get(online_cfg_key, cfg.get("online_controller", {})))
        gate = None
    elif pipeline_key == "P2_FrameDiff":
        gate = FrameDiffGate(min_area_ratio=cfg.get("p4_asmag_plus", {}).get("min_area_ratio", 0.001))
    elif pipeline_key == "P3_MOG2":
        gate = MOG2Gate(min_area_ratio=cfg.get("p4_asmag_plus", {}).get("min_area_ratio", 0.001))
    elif pipeline_key == "P4_ASMAG_PLUS":
        gate = ASMAGPlusGate(cfg.get("p4_asmag_plus", {}))
    elif pipeline_key == "P4_ASMAG_PLUS_PRECISION":
        precision_cfg = dict(cfg.get("p4_asmag_plus", {}))
        precision_cfg.update(cfg.get("p4_precision", {}))
        gate = ASMAGPlusPrecisionGate(precision_cfg)
    elif pipeline_key == "P4_ASMAG_PLUS_BALANCED":
        balanced_cfg = dict(cfg.get("p4_asmag_plus", {}))
        balanced_cfg.update(cfg.get("p4_balanced", {}))
        gate = ASMAGPlusBalancedGate(balanced_cfg)
    elif pipeline_key in {"P4_ASMAG_PLUS_EFFICIENT", "P4_ASMAG_PLUS_EFFICIENT_REUSE"}:
        gate = ASMAGPlusEfficientGate(p4_efficient_cfg_for_pipeline(cfg, execution_pipeline_name))
    else:
        gate = None

    proc = psutil.Process(os.getpid())
    proc.cpu_percent(interval=None)
    edge = cfg.get("edge_profile", {})
    delay = float(edge.get("delay_penalty_sec", 0.0))
    cores = int(edge.get("simulated_cores", 2))
    ram_gb = float(edge.get("simulated_ram_gb", 4))

    rows, px_rows, edge_rows, object_records = [], [], [], []
    p4_diagnostics = []
    prev = None
    yolo_calls = 0
    processed = 0
    warmup_processed = 0
    reused_predictions = 0
    last_valid_pred_mask = None
    last_detection_frame_id = None
    last_detection_eval_index = None
    last_detection_raw_frame_id = None
    guarded_previous_mode = ""
    guarded_last_forced_refresh_eval_index = -10**9
    guarded_last_p3_guard_eval_index = -10**9
    guarded_last_global_motion_refresh_eval_index = -10**9
    guarded_last_night_refresh_eval_index = -10**9
    guarded_consecutive_p3_guard_frames = 0
    guarded_consecutive_closed_empty_frames = 0
    guarded_ptz_safe_fallback_burst = 0
    guarded_overload_until_eval_index = -10**9
    guarded_consecutive_global_motion_frames = 0
    guarded_last_legacy_safe_eval_index = -10**9
    guarded_legacy_safe_burst = 0
    guarded_legacy_safe_cooldown_until_eval_index = -10**9
    guarded_last_active_prediction_eval_index = -10**9
    guarded_recent_low_trust_actions = []
    guarded_legacy_safe_total_frames = 0
    guarded_ptz_emergency_burst_age = 0
    guarded_ptz_emergency_cooldown_until_eval_index = -10**9
    guarded_rolling_global_motion_flags = []
    guarded_rolling_acc_global_flags = []
    guarded_rolling_low_trust_flags = []
    guarded_rolling_closed_empty_motion_flags = []
    guarded_ptz_detector_floor_refresh_indices = []
    guarded_position_switch_until_eval_index = -10**9
    guarded_position_switch_refresh_until_eval_index = -10**9
    guarded_position_switch_reset_start_eval_index = -10**9
    guarded_recent_legacy_safe_flags = []
    guarded_recent_detect_acc_flags = []
    guarded_recent_detector_like_flags = []
    guarded_recent_non_ptz_motion_comp_behavior_flags = []
    guarded_recent_continuous_pan_shifts = []
    guarded_recent_continuous_pan_reuse_acc_flags = []
    guarded_recent_continuous_pan_detector_anchor_flags = []
    guarded_last_continuous_pan_anchor_eval_index = -10**9
    guarded_previous_detector_latency_ms = 0.0
    guarded_previous_total_latency_ms = 0.0
    job_started_at = time.time()
    progress_cfg = cfg.get("progress", {})
    write_progress_every_frames = max(1, int(progress_cfg.get("write_progress_every_frames", 25)))
    progress_monitor = None
    if progress_path is not None:
        progress_monitor = ProgressMonitor(out_root, progress_path, cfg, session_started_at=session_started_at)

    for idx in warmup_positions:
        frame = read_frame(frame_files[idx])
        if frame is None:
            continue
        if is_guarded_online_controller:
            guarded_gate_bank.process(frame, prev, {"is_evaluation": False})
        elif is_online_controller:
            for online_gate in online_gates.values():
                online_gate.process(frame, prev)
        else:
            gate.process(frame, prev)
        prev = frame.copy()
        warmup_processed += 1

    if warmup_processed and is_guarded_online_controller:
        guarded_gate_bank.reset_runtime_state()
    elif warmup_processed and is_online_controller:
        for online_gate in online_gates.values():
            if hasattr(online_gate, "reset_runtime_state"):
                online_gate.reset_runtime_state()
    elif warmup_processed and hasattr(gate, "reset_runtime_state"):
        gate.reset_runtime_state()

    for idx in loop_positions:
        if frames_source is None:
            frame = read_frame(frame_files[idx])
            if frame is None:
                continue
            gt = read_gt_for_frame(gt_by_number, frame_files[idx], frame.shape)
        else:
            frame = frames_source[idx]
            gt = gts_source[idx]

        should_evaluate = idx in eval_position_set
        if not should_evaluate:
            if is_guarded_online_controller:
                guarded_gate_bank.process(frame, prev, {"is_evaluation": False})
            elif is_online_controller:
                for online_gate in online_gates.values():
                    online_gate.process(frame, prev, {"is_evaluation": False})
            elif pipeline_key != "P1_YOLO_Only":
                gate.process(frame, prev, {"is_evaluation": False})
            prev = frame.copy()
            continue

